export type UserRole = 'master' | 'basic';

export interface ServiceCategory {
  id: string;
  name: string;
  color: string;
}

export interface Person {
  id: string;
  name: string;
  role: string;
}

export interface Task {
  id: string;
  personId: string;
  serviceCategoryId: string; 
  invoiceQuantity: number; // Qtd de Notas Fiscais
  date: string; // ISO date string YYYY-MM-DD
  processQuantity: number; // Qtd de Processos (antigo quantity)
  assignedProcesses: number; // Qtd de Processos Atribuídos
}

export interface AppState {
  people: Person[];
  tasks: Task[];
  serviceCategories: ServiceCategory[];
  userRole: UserRole;
}

import React, { useState, useMemo } from 'react';
import { Person, Task, ServiceCategory, UserRole } from '../types';
import { Icons } from '../constants';

interface DailyLogProps {
  tasks: Task[];
  people: Person[];
  categories: ServiceCategory[];
  onAddTask: (task: Task) => void;
  onEditTask: (task: Task) => void;
  onRemoveTask: (id: string) => void;
  userRole: UserRole;
}

const DailyLog: React.FC<DailyLogProps> = ({ tasks, people, categories, onAddTask, onEditTask, onRemoveTask, userRole }) => {
  const getLocalDateStr = () => {
    const d = new Date();
    const offset = d.getTimezoneOffset();
    const localDate = new Date(d.getTime() - (offset * 60 * 1000));
    return localDate.toISOString().split('T')[0];
  };

  const [selectedPerson, setSelectedPerson] = useState('');
  const [selectedCategoryId, setSelectedCategoryId] = useState('');
  const [assignedProcesses, setAssignedProcesses] = useState<number>(0);
  const [processQuantity, setProcessQuantity] = useState<number>(1);
  const [invoiceQuantity, setInvoiceQuantity] = useState<number>(0);
  const [date, setDate] = useState(getLocalDateStr());

  const [filterDate, setFilterDate] = useState(getLocalDateStr());
  const [editingTaskId, setEditingTaskId] = useState<string | null>(null);

  const filteredTasks = useMemo(() => {
    return tasks
      .filter(t => t.date === filterDate)
      .sort((a, b) => b.id.localeCompare(a.id));
  }, [tasks, filterDate]);

  const handleSaveTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPerson || !selectedCategoryId) return;

    const taskData: Task = {
      id: editingTaskId || Math.random().toString(36).substr(2, 9),
      personId: selectedPerson,
      serviceCategoryId: selectedCategoryId,
      assignedProcesses: Number(assignedProcesses),
      processQuantity: Number(processQuantity),
      invoiceQuantity: Number(invoiceQuantity),
      date
    };

    if (editingTaskId) {
      onEditTask(taskData);
      setEditingTaskId(null);
    } else {
      onAddTask(taskData);
    }

    setAssignedProcesses(0);
    setProcessQuantity(1);
    setInvoiceQuantity(0);
    setSelectedPerson('');
    setSelectedCategoryId('');
  };

  const startEdit = (task: Task) => {
    setEditingTaskId(task.id);
    setSelectedPerson(task.personId);
    setSelectedCategoryId(task.serviceCategoryId);
    setAssignedProcesses(task.assignedProcesses || 0);
    setProcessQuantity(task.processQuantity);
    setInvoiceQuantity(task.invoiceQuantity);
    setDate(task.date);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const cancelEdit = () => {
    setEditingTaskId(null);
    setAssignedProcesses(0);
    setProcessQuantity(1);
    setInvoiceQuantity(0);
    setSelectedPerson('');
    setSelectedCategoryId('');
  };

  return (
    <div className="space-y-8 pb-10">
      <div className={`bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-sm border transition-all ${editingTaskId ? 'border-amber-400 ring-4 ring-amber-50 dark:ring-amber-900/20' : 'border-slate-200 dark:border-slate-800'}`}>
        <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 mb-8 flex items-center gap-2">
          {editingTaskId ? <Icons.Edit /> : <Icons.Plus />}
          {editingTaskId ? 'Editar Lançamento' : 'Novo Registro de Produção'}
        </h3>
        <form onSubmit={handleSaveTask} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-7 gap-4 items-end">
          <div className="lg:col-span-1">
            <label className="block text-[10px] font-black uppercase text-slate-400 dark:text-slate-500 mb-1.5 tracking-wider">Data</label>
            <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full px-4 py-3 rounded-2xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-800 dark:text-white outline-none focus:ring-2 focus:ring-blue-500 transition-all text-xs font-medium" />
          </div>
          <div className="lg:col-span-1">
            <label className="block text-[10px] font-black uppercase text-slate-400 dark:text-slate-500 mb-1.5 tracking-wider">Colaborador</label>
            <select value={selectedPerson} onChange={(e) => setSelectedPerson(e.target.value)} className="w-full px-4 py-3 rounded-2xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-800 dark:text-white outline-none focus:ring-2 focus:ring-blue-500 transition-all text-xs font-medium" required>
              <option value="">Selecione...</option>
              {people.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
            </select>
          </div>
          <div className="lg:col-span-1">
            <label className="block text-[10px] font-black uppercase text-slate-400 dark:text-slate-500 mb-1.5 tracking-wider">Serviço</label>
            <select value={selectedCategoryId} onChange={(e) => setSelectedCategoryId(e.target.value)} className="w-full px-4 py-3 rounded-2xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-800 dark:text-white outline-none focus:ring-2 focus:ring-blue-500 transition-all text-xs font-medium" required>
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
            </select>
          </div>
          <div className="lg:col-span-1">
            <label className="block text-[10px] font-black uppercase text-slate-400 dark:text-slate-500 mb-1.5 tracking-wider">Proc. Atribuídos</label>
            <input type="number" min="0" value={assignedProcesses} onChange={(e) => setAssignedProcesses(parseInt(e.target.value) || 0)} className="w-full px-4 py-3 rounded-2xl border border-indigo-200 dark:border-indigo-800 bg-white dark:bg-slate-800 outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold text-indigo-600 dark:text-indigo-400 text-sm" />
          </div>
          <div className="lg:col-span-1">
            <label className="block text-[10px] font-black uppercase text-slate-400 dark:text-slate-500 mb-1.5 tracking-wider">Qtd. Realizada</label>
            <input type="number" min="0" value={processQuantity} onChange={(e) => setProcessQuantity(parseInt(e.target.value) || 0)} className="w-full px-4 py-3 rounded-2xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-800 dark:text-white outline-none focus:ring-2 focus:ring-blue-500 transition-all font-bold text-sm" />
          </div>
          <div className="lg:col-span-1">
            <label className="block text-[10px] font-black uppercase text-slate-400 dark:text-slate-500 mb-1.5 tracking-wider">Notas Fiscais</label>
            <input type="number" min="0" value={invoiceQuantity} onChange={(e) => setInvoiceQuantity(parseInt(e.target.value) || 0)} className="w-full px-4 py-3 rounded-2xl border border-emerald-200 dark:border-emerald-800 bg-white dark:bg-slate-800 outline-none focus:ring-2 focus:ring-emerald-500 transition-all font-bold text-emerald-600 dark:text-emerald-400 text-sm" />
          </div>
          <div className="flex gap-2">
            <button type="submit" className={`flex-1 ${editingTaskId ? 'bg-amber-500' : 'bg-blue-600'} text-white py-3.5 rounded-2xl font-bold shadow-lg transition-all active:scale-95 text-xs uppercase tracking-widest`}>
              {editingTaskId ? 'SALVAR' : 'LANÇAR'}
            </button>
            {editingTaskId && (
              <button onClick={cancelEdit} className="bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 px-3 py-3.5 rounded-2xl font-bold hover:bg-slate-200 dark:hover:bg-slate-700 transition-all text-xs">
                X
              </button>
            )}
          </div>
        </form>
      </div>

      <div className="bg-white dark:bg-slate-900 rounded-3xl shadow-sm border border-slate-200 dark:border-slate-800 overflow-hidden transition-colors">
        <div className="p-8 border-b border-slate-100 dark:border-slate-800 flex flex-col sm:flex-row justify-between items-center gap-4">
          <h3 className="text-xl font-extrabold text-slate-800 dark:text-slate-100 tracking-tight">Histórico de Lançamentos</h3>
          <div className="flex items-center gap-3 bg-slate-50 dark:bg-slate-800 px-4 py-2 rounded-2xl border border-slate-100 dark:border-slate-700">
            <span className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase">Dia:</span>
            <input type="date" value={filterDate} onChange={(e) => setFilterDate(e.target.value)} className="bg-transparent text-sm font-bold text-slate-700 dark:text-slate-200 outline-none" />
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50/50 dark:bg-slate-800/50 text-slate-500 dark:text-slate-400 text-[10px] font-black uppercase tracking-widest">
              <tr>
                <th className="px-8 py-5">Colaborador</th>
                <th className="px-8 py-5">Serviço</th>
                <th className="px-8 py-5 text-center">Atribuídos</th>
                <th className="px-8 py-5 text-center">Realizados</th>
                <th className="px-8 py-5 text-center">Notas</th>
                <th className="px-8 py-5 text-right">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
              {filteredTasks.length === 0 ? (
                <tr>
                  <td colSpan={6} className="px-8 py-16 text-center text-slate-400 dark:text-slate-600">
                    <div className="flex flex-col items-center gap-3">
                      <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-full">
                        <Icons.Calendar />
                      </div>
                      <p className="font-bold text-sm uppercase tracking-widest">Nenhum registro para este dia.</p>
                    </div>
                  </td>
                </tr>
              ) : (
                filteredTasks.map((task) => {
                  const person = people.find(p => p.id === task.personId);
                  const category = categories.find(c => c.id === task.serviceCategoryId);
                  return (
                    <tr key={task.id} className="hover:bg-slate-50/80 dark:hover:bg-slate-800/50 transition-colors group">
                      <td className="px-8 py-6">
                        <div className="flex items-center gap-3">
                          <div className="w-10 h-10 rounded-xl bg-slate-100 dark:bg-slate-800 flex items-center justify-center font-bold text-slate-500 dark:text-slate-400 text-sm">
                            {person?.name.charAt(0).toUpperCase()}
                          </div>
                          <div>
                            <p className="font-bold text-slate-800 dark:text-slate-100 text-sm">{person?.name || '??'}</p>
                            <p className="text-[10px] text-slate-400 dark:text-slate-500 uppercase font-black">{person?.role}</p>
                          </div>
                        </div>
                      </td>
                      <td className="px-8 py-6">
                        <span className="px-3 py-1.5 rounded-lg text-[10px] font-black text-white shadow-sm" style={{ backgroundColor: category?.color }}>
                          {category?.name}
                        </span>
                      </td>
                      <td className="px-8 py-6 text-center">
                        <span className="text-sm font-black text-indigo-600 dark:text-indigo-400">{task.assignedProcesses || 0}</span>
                      </td>
                      <td className="px-8 py-6 text-center">
                        <span className="text-sm font-black text-slate-800 dark:text-slate-200">{task.processQuantity}</span>
                      </td>
                      <td className="px-8 py-6 text-center">
                        <span className="text-sm font-black text-emerald-600 dark:text-emerald-400">{task.invoiceQuantity}</span>
                      </td>
                      <td className="px-8 py-6 text-right">
                        {userRole === 'master' && (
                          <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={() => startEdit(task)} className="p-2.5 text-slate-400 dark:text-slate-500 hover:text-blue-600 dark:hover:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-xl transition-all" title="Editar"><Icons.Edit /></button>
                            <button onClick={() => onRemoveTask(task.id)} className="p-2.5 text-slate-400 dark:text-slate-500 hover:text-red-600 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-xl transition-all" title="Excluir"><Icons.Trash /></button>
                          </div>
                        )}
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default DailyLog;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, AreaChart, Area, LabelList
} from 'recharts';
import { AppState, Task, ServiceCategory } from '../types';
import { Icons } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
  onRefresh?: () => Promise<void>;
}

type TabType = 'common' | 'special';
type PeriodPreset = 'hoje' | 'semanal' | 'quinzenal' | 'mensal' | 'trimestral' | 'anual' | 'custom';

const Dashboard: React.FC<DashboardProps> = ({ state, onRefresh }) => {
  const getLocalDateStr = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset();
    const localDate = new Date(d.getTime() - (offset * 60 * 1000));
    return localDate.toISOString().split('T')[0];
  };

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>(getLocalDateStr());
  const [activePreset, setActivePreset] = useState<PeriodPreset>('mensal');
  const [selectedPeopleIds, setSelectedPeopleIds] = useState<string[]>([]);
  const [activeTab, setActiveTab] = useState<TabType>('common');
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  useEffect(() => {
    const now = new Date();
    let start = new Date();

    switch (activePreset) {
      case 'hoje': break;
      case 'semanal': start.setDate(now.getDate() - 7); break;
      case 'quinzenal': start.setDate(now.getDate() - 15); break;
      case 'mensal': start.setDate(now.getDate() - 30); break;
      case 'trimestral': start.setDate(now.getDate() - 90); break;
      case 'anual': start.setDate(now.getDate() - 365); break;
      case 'custom': return;
    }

    setStartDate(getLocalDateStr(start));
    setEndDate(getLocalDateStr(now));
  }, [activePreset]);

  const isSpecialCategory = (categoryId: string) => {
    const cat = state.serviceCategories.find(c => c.id === categoryId);
    if (!cat) return false;
    const name = cat.name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    return name.includes('licitacao') || name.includes('diaria') || name.includes('contrato');
  };

  const togglePerson = (id: string) => {
    setSelectedPeopleIds(prev => 
      prev.includes(id) ? prev.filter(pId => pId !== id) : [...prev, id]
    );
  };

  const handleManualRefresh = async () => {
    if (onRefresh) {
      setIsRefreshing(true);
      await onRefresh();
      setTimeout(() => setIsRefreshing(false), 600);
    }
  };

  const filteredTasks = useMemo(() => {
    const tasks = state.tasks || [];
    return tasks.filter(t => {
      const dateMatch = (!startDate || t.date >= startDate) && (!endDate || t.date <= endDate);
      const personMatch = selectedPeopleIds.length === 0 || selectedPeopleIds.includes(t.personId);
      return dateMatch && personMatch;
    });
  }, [state.tasks, startDate, endDate, selectedPeopleIds]);

  const commonTasks = filteredTasks.filter(t => !isSpecialCategory(t.serviceCategoryId));
  const specialTasks = filteredTasks.filter(t => isSpecialCategory(t.serviceCategoryId));

  const barData = useMemo(() => {
    const dateFilteredOnly = (state.tasks || []).filter(t => (!startDate || t.date >= startDate) && (!endDate || t.date <= endDate));
    const tasksToCalculate = dateFilteredOnly.filter(t => !isSpecialCategory(t.serviceCategoryId));

    return (state.people || []).map(person => {
      const pTasks = tasksToCalculate.filter(t => t.personId === person.id);
      const atribuidos = pTasks.reduce((acc, t) => acc + (Number(t.assignedProcesses) || 0), 0);
      const realizados = pTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0);
      const notas = pTasks.reduce((acc, t) => acc + (Number(t.invoiceQuantity) || 0), 0);

      return {
        id: person.id,
        name: person.name,
        atribuidos,
        realizados,
        notas,
        opacity: selectedPeopleIds.length === 0 || selectedPeopleIds.includes(person.id) ? 1 : 0.3
      };
    }).filter(d => d.atribuidos > 0 || d.realizados > 0 || d.notas > 0).sort((a, b) => b.atribuidos - a.atribuidos);
  }, [state.people, state.tasks, startDate, endDate, selectedPeopleIds]);

  const areaData = useMemo(() => {
    const map: Record<string, any> = {};
    commonTasks.forEach(t => {
      if (!map[t.date]) map[t.date] = { date: t.date, atribuidos: 0, realizados: 0, notas: 0 };
      map[t.date].atribuidos += (Number(t.assignedProcesses) || 0);
      map[t.date].realizados += (Number(t.processQuantity) || 0);
      map[t.date].notas += (Number(t.invoiceQuantity) || 0);
    });
    return Object.values(map)
      .filter((d: any) => d.atribuidos > 0 || d.realizados > 0 || d.notas > 0)
      .sort((a: any, b: any) => a.date.localeCompare(b.date));
  }, [commonTasks]);

  const handleGetInsights = async () => {
    if (filteredTasks.length === 0) return;
    setLoadingAi(true);
    try {
      const insight = await getProductivityInsights(filteredTasks, state.people, state.serviceCategories);
      setAiInsight(insight);
    } catch (e) {
      setAiInsight("Erro ao gerar análise inteligente.");
    } finally {
      setLoadingAi(false);
    }
  };

  const presets: { id: PeriodPreset, label: string }[] = [
    { id: 'hoje', label: 'Hoje' },
    { id: 'semanal', label: 'Semanal' },
    { id: 'quinzenal', label: 'Quinzenal' },
    { id: 'mensal', label: 'Mensal' },
    { id: 'anual', label: 'Anual' },
    { id: 'custom', label: 'Personalizado' }
  ];

  const EmptyNotice = ({ msg }: { msg: string }) => (
    <div className="flex flex-col items-center justify-center h-full p-10 bg-slate-50 dark:bg-slate-800/50 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-[32px] text-slate-300 dark:text-slate-600 transition-colors">
      <div className="opacity-20"><Icons.Calendar /></div>
      <p className="mt-4 font-black text-[10px] uppercase tracking-widest text-slate-400 dark:text-slate-500 text-center">{msg}</p>
    </div>
  );

  return (
    <div className="space-y-8 pb-20 fade-in">
      {/* FILTROS */}
      <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[32px] md:rounded-[40px] shadow-sm border border-slate-200 dark:border-slate-800 space-y-6 md:space-y-8 transition-colors">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
          <div className="space-y-1">
            <h3 className="text-xl font-black text-slate-800 dark:text-slate-100 uppercase tracking-tight">Análise Gerencial</h3>
            <p className="text-xs text-slate-400 dark:text-slate-500 font-bold">Monitoramento de Atribuições e Realizações</p>
          </div>
          <div className="flex p-1 bg-slate-100 dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 overflow-x-auto custom-scrollbar">
            {[
              { id: 'common', label: 'PROCESSOS / ATRIBUIÇÕES' },
              { id: 'special', label: 'LICITAÇÃO / DIÁRIA' }
            ].map(tab => (
              <button 
                key={tab.id}
                onClick={() => setActiveTab(tab.id as TabType)}
                className={`px-4 md:px-6 py-2 md:py-2.5 rounded-xl text-[9px] md:text-[10px] font-black tracking-widest transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm border border-slate-200 dark:border-slate-600' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600 dark:hover:text-slate-300'}`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        <div className="pt-6 md:pt-8 border-t border-slate-100 dark:border-slate-800">
           <div className="flex flex-wrap gap-2">
              {presets.map(p => (
                <button key={p.id} onClick={() => setActivePreset(p.id)} className={`px-3 md:px-4 py-2 rounded-xl text-[9px] md:text-[10px] font-black border transition-all ${activePreset === p.id ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'bg-white dark:bg-slate-800 text-slate-400 dark:text-slate-500 border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700'}`}>
                  {p.label.toUpperCase()}
                </button>
              ))}
              <button onClick={handleManualRefresh} disabled={isRefreshing} className="ml-auto flex items-center gap-2 px-3 py-1.5 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:text-blue-600 transition-all active:scale-95 disabled:opacity-50">
                <div className={isRefreshing ? 'animate-spin-slow' : ''}><Icons.Refresh /></div>
              </button>
            </div>
        </div>
      </div>

      {/* CARDS COM NOVA ORDEM */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 md:gap-6">
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-indigo-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Processos Atribuídos</p>
          <h4 className="text-3xl md:text-4xl font-black text-indigo-600 dark:text-indigo-400 mt-1 md:mt-2">{filteredTasks.reduce((acc, t) => acc + (Number(t.assignedProcesses) || 0), 0)}</h4>
        </div>
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-blue-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Processos Realizados</p>
          <h4 className="text-3xl md:text-4xl font-black text-blue-600 dark:text-blue-500 mt-1 md:mt-2">{commonTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0)}</h4>
        </div>
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-emerald-500 transition-colors">
