import React, { useState, useEffect } from 'react';
import { Person, Task, AppState, ServiceCategory, UserRole } from './types';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import PeopleManager from './components/PeopleManager';
import DailyLog from './components/DailyLog';
import ServiceManager from './components/ServiceManager';
import Login from './components/Login';
import { DEFAULT_CATEGORIES } from './constants';
import { apiService } from './services/api';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'people' | 'logs' | 'services'>('dashboard');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('app-theme');
    return (saved as 'light' | 'dark') || 'light';
  });

  const [state, setState] = useState<AppState>({ 
    people: [], 
    tasks: [], 
    serviceCategories: DEFAULT_CATEGORIES,
    userRole: 'master' 
  });

  const loadData = async () => {
    try {
      const savedState = await apiService.loadState();
      if (savedState) setState(savedState);
    } catch (error) {
      console.error("Erro no carregamento:", error);
    }
  };

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('app-theme', theme);
  }, [theme]);

  useEffect(() => {
    async function init() {
      await loadData();
      setTimeout(() => setIsLoading(false), 800);
    }
    init();
  }, []);

  const persistState = async (newState: AppState) => {
    setState(newState);
    await apiService.saveState(newState);
  };

  const handleLogin = (role: UserRole) => {
    setState(prev => ({ ...prev, userRole: role }));
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setActiveTab('dashboard');
  };

  const setUserRole = (role: UserRole) => {
    persistState({ ...state, userRole: role });
    if (role === 'basic' && (activeTab === 'people' || activeTab === 'services')) {
      setActiveTab('dashboard');
    }
  };

  const toggleTheme = () => setTheme(prev => prev === 'light' ? 'dark' : 'light');

  const addPerson = (person: Person) => {
    if (state.userRole !== 'master') return;
    persistState({ ...state, people: [...state.people, person] });
  };

  const removePerson = (id: string) => {
    if (state.userRole !== 'master') return;
    persistState({
      ...state,
      people: state.people.filter(p => p.id !== id),
      tasks: state.tasks.filter(t => t.personId !== id)
    });
  };

  const addTask = (task: Task) => {
    persistState({ ...state, tasks: [...state.tasks, task] });
  };

  const editTask = (updatedTask: Task) => {
    persistState({
      ...state,
      tasks: state.tasks.map(t => t.id === updatedTask.id ? updatedTask : t)
    });
  };

  const removeTask = (id: string) => {
    // Permissão estendida para nível básico conforme solicitação
    persistState({
      ...state,
      tasks: state.tasks.filter(t => t.id !== id)
    });
  };

  const addServiceCategory = (cat: ServiceCategory) => {
    if (state.userRole !== 'master') return;
    persistState({ ...state, serviceCategories: [...state.serviceCategories, cat] });
  };

  const removeServiceCategory = (id: string) => {
    if (state.userRole !== 'master') return;
    persistState({
      ...state,
      serviceCategories: state.serviceCategories.filter(c => c.id !== id),
      tasks: state.tasks.filter(t => t.serviceCategoryId !== id)
    });
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex flex-col items-center justify-center transition-colors">
        <div className="relative">
          <div className="w-20 h-20 border-4 border-blue-100 dark:border-slate-800 border-t-blue-600 rounded-full animate-spin"></div>
          <div className="absolute inset-0 flex items-center justify-center">
             <svg className="w-8 h-8 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
          </div>
        </div>
        <p className="mt-6 font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest text-xs animate-pulse">Carregando dados do servidor...</p>
      </div>
    );
  }

  if (!isLoggedIn) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="flex min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 transition-colors">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        userRole={state.userRole}
        onRoleChange={setUserRole}
        onLogout={handleLogout}
        theme={theme}
        toggleTheme={toggleTheme}
      />

      <main className="flex-1 p-6 md:p-10 overflow-auto">
        <header className="mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h1 className="text-3xl font-bold text-slate-800 dark:text-slate-100 mb-1">
              {activeTab === 'dashboard' && 'Visão Geral'}
              {activeTab === 'people' && 'Gerenciar Equipe'}
              {activeTab === 'logs' && 'Registro Diário'}
              {activeTab === 'services' && 'Tipos de Serviço'}
            </h1>
            <p className="text-slate-500 dark:text-slate-400 font-medium">
              {activeTab === 'dashboard' && 'Monitore a produtividade e o desempenho da equipe.'}
              {activeTab === 'people' && 'Adicione ou remova membros da sua equipe.'}
              {activeTab === 'logs' && 'Visualize e gerencie os serviços realizados diariamente.'}
              {activeTab === 'services' && 'Personalize as categorias e gerencie a base de dados.'}
            </p>
          </div>

          <div className="flex items-center gap-3">
             <div className={`px-4 py-2 rounded-2xl text-[10px] font-bold uppercase tracking-widest shadow-sm ${
              state.userRole === 'master' ? 'bg-indigo-600 text-white' : 'bg-emerald-600 text-white'
            }`}>
              {state.userRole === 'master' ? 'Acesso Master' : 'Acesso Básico'}
            </div>
          </div>
        </header>

        {activeTab === 'dashboard' && <Dashboard state={state} onRefresh={loadData} />}
        {activeTab === 'people' && state.userRole === 'master' && (
          <PeopleManager people={state.people} onAdd={addPerson} onRemove={removePerson} />
        )}
        {activeTab === 'logs' && (
          <DailyLog 
            tasks={state.tasks} 
            people={state.people} 
            categories={state.serviceCategories}
            onAddTask={addTask} 
            onEditTask={editTask}
            onRemoveTask={removeTask}
            userRole={state.userRole}
          />
        )}
        {activeTab === 'services' && state.userRole === 'master' && (
          <ServiceManager 
            categories={state.serviceCategories} 
            onAdd={addServiceCategory} 
            onRemove={removeServiceCategory} 
            state={state}
            onImport={(imported) => persistState(imported)}
          />
        )}

        {(activeTab === 'people' || activeTab === 'services') && state.userRole === 'basic' && (
          <div className="bg-white dark:bg-slate-900 p-12 rounded-3xl shadow-sm border border-slate-200 dark:border-slate-800 text-center">
            <h2 className="text-2xl font-bold text-slate-800 dark:text-slate-100 mb-2">Acesso Restrito</h2>
            <p className="text-slate-500 dark:text-slate-400">Perfil operacional sem permissões administrativas.</p>
            <button 
              onClick={() => setActiveTab('dashboard')}
              className="mt-8 bg-slate-900 dark:bg-blue-600 text-white px-8 py-3 rounded-2xl font-bold hover:bg-black dark:hover:bg-blue-700 transition-all"
            >
              Retornar ao Painel
            </button>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, AreaChart, Area, LabelList
} from 'recharts';
import { AppState, Task, ServiceCategory } from '../types';
import { Icons, PRESET_COLORS } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
  onRefresh?: () => Promise<void>;
}

type TabType = 'common' | 'special';
type PeriodPreset = 'hoje' | 'semanal' | 'quinzenal' | 'mensal' | 'trimestral' | 'anual' | 'custom';

const Dashboard: React.FC<DashboardProps> = ({ state, onRefresh }) => {
  const getLocalDateStr = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset();
    const localDate = new Date(d.getTime() - (offset * 60 * 1000));
    return localDate.toISOString().split('T')[0];
  };

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>(getLocalDateStr());
  const [activePreset, setActivePreset] = useState<PeriodPreset>('mensal');
  const [selectedPeopleIds, setSelectedPeopleIds] = useState<string[]>([]);
  const [activeTab, setActiveTab] = useState<TabType>('common');
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  useEffect(() => {
    const now = new Date();
    let start = new Date();

    switch (activePreset) {
      case 'hoje': break;
      case 'semanal': start.setDate(now.getDate() - 7); break;
      case 'quinzenal': start.setDate(now.getDate() - 15); break;
      case 'mensal': start.setDate(now.getDate() - 30); break;
      case 'trimestral': start.setDate(now.getDate() - 90); break;
      case 'anual': start.setDate(now.getDate() - 365); break;
      case 'custom': return;
    }

    setStartDate(getLocalDateStr(start));
    setEndDate(getLocalDateStr(now));
  }, [activePreset]);

  const isSpecialCategory = (categoryId: string) => {
    const cat = state.serviceCategories.find(c => c.id === categoryId);
    if (!cat) return false;
    const name = cat.name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    return name.includes('licitacao') || name.includes('diaria') || name.includes('contrato');
  };

  const togglePerson = (id: string) => {
    setSelectedPeopleIds(prev => 
      prev.includes(id) ? prev.filter(pId => pId !== id) : [...prev, id]
    );
  };

  const handleManualRefresh = async () => {
    if (onRefresh) {
      setIsRefreshing(true);
      await onRefresh();
      setTimeout(() => setIsRefreshing(false), 600);
    }
  };

  const filteredTasks = useMemo(() => {
    const tasks = state.tasks || [];
    return tasks.filter(t => {
      const dateMatch = (!startDate || t.date >= startDate) && (!endDate || t.date <= endDate);
      const personMatch = selectedPeopleIds.length === 0 || selectedPeopleIds.includes(t.personId);
      return dateMatch && personMatch;
    });
  }, [state.tasks, startDate, endDate, selectedPeopleIds]);

  const commonTasks = filteredTasks.filter(t => !isSpecialCategory(t.serviceCategoryId));
  const specialTasks = filteredTasks.filter(t => isSpecialCategory(t.serviceCategoryId));

  // Gráfico de Barras: Atribuídos, Realizados e Notas por Analista
  const barData = useMemo(() => {
    const tasksToCalculate = commonTasks;
    return (state.people || []).map(person => {
      const pTasks = tasksToCalculate.filter(t => t.personId === person.id);
      const atribuidos = pTasks.reduce((acc, t) => acc + (Number(t.assignedProcesses) || 0), 0);
      const realizados = pTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0);
      const notas = pTasks.reduce((acc, t) => acc + (Number(t.invoiceQuantity) || 0), 0);

      return {
        id: person.id,
        name: person.name,
        atribuidos,
        realizados,
        notas,
        opacity: selectedPeopleIds.length === 0 || selectedPeopleIds.includes(person.id) ? 1 : 0.3
      };
    }).filter(d => d.atribuidos > 0 || d.realizados > 0 || d.notas > 0).sort((a, b) => b.realizados - a.realizados);
  }, [state.people, commonTasks, selectedPeopleIds]);

  // Gráfico de Tendência: Evolução Temporal de Realizados
  const areaData = useMemo(() => {
    const map: Record<string, any> = {};
    commonTasks.forEach(t => {
      if (!map[t.date]) map[t.date] = { date: t.date, realizados: 0 };
      map[t.date].realizados += (Number(t.processQuantity) || 0);
    });
    return Object.values(map)
      .sort((a: any, b: any) => a.date.localeCompare(b.date));
  }, [commonTasks]);

  // Gráfico de Pizza: Tipos de Serviços
  const pieData = useMemo(() => {
    const map: Record<string, number> = {};
    commonTasks.forEach(t => {
      const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
      const name = cat?.name || 'Outros';
      map[name] = (map[name] || 0) + (Number(t.processQuantity) || 0);
    });
    return Object.entries(map).map(([name, value]) => ({ name, value }));
  }, [commonTasks, state.serviceCategories]);

  const handleGetInsights = async () => {
    if (filteredTasks.length === 0) return;
    setLoadingAi(true);
    try {
      const insight = await getProductivityInsights(filteredTasks, state.people, state.serviceCategories);
      setAiInsight(insight);
    } catch (e) {
      setAiInsight("Erro ao gerar análise inteligente.");
    } finally {
      setLoadingAi(false);
    }
  };

  const presets: { id: PeriodPreset, label: string }[] = [
    { id: 'hoje', label: 'Hoje' },
    { id: 'semanal', label: 'Semanal' },
    { id: 'quinzenal', label: 'Quinzenal' },
    { id: 'mensal', label: 'Mensal' },
    { id: 'anual', label: 'Anual' },
    { id: 'custom', label: 'Personalizado' }
  ];

  const EmptyNotice = ({ msg }: { msg: string }) => (
    <div className="flex flex-col items-center justify-center h-full p-10 bg-slate-50 dark:bg-slate-800/50 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-[32px] text-slate-300 dark:text-slate-600 transition-colors">
      <div className="opacity-20"><Icons.Calendar /></div>
      <p className="mt-4 font-black text-[10px] uppercase tracking-widest text-slate-400 dark:text-slate-500 text-center">{msg}</p>
    </div>
  );

  return (
    <div className="space-y-8 pb-20 fade-in">
      {/* FILTROS */}
      <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[32px] md:rounded-[40px] shadow-sm border border-slate-200 dark:border-slate-800 space-y-6 md:space-y-8 transition-colors">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
          <div className="space-y-1">
            <h3 className="text-xl font-black text-slate-800 dark:text-slate-100 uppercase tracking-tight">Análise Gerencial</h3>
            <p className="text-xs text-slate-400 dark:text-slate-500 font-bold">Monitoramento de Atribuições e Realizações</p>
          </div>
          <div className="flex p-1 bg-slate-100 dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 overflow-x-auto custom-scrollbar">
            {[
              { id: 'common', label: 'PROCESSOS / ATRIBUIÇÕES' },
              { id: 'special', label: 'LICITAÇÃO / DIÁRIA' }
            ].map(tab => (
              <button 
                key={tab.id}
                onClick={() => setActiveTab(tab.id as TabType)}
                className={`px-4 md:px-6 py-2 md:py-2.5 rounded-xl text-[9px] md:text-[10px] font-black tracking-widest transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm border border-slate-200 dark:border-slate-600' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600 dark:hover:text-slate-300'}`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        <div className="pt-6 md:pt-8 border-t border-slate-100 dark:border-slate-800">
           <div className="flex flex-wrap gap-2">
              {presets.map(p => (
                <button key={p.id} onClick={() => setActivePreset(p.id)} className={`px-3 md:px-4 py-2 rounded-xl text-[9px] md:text-[10px] font-black border transition-all ${activePreset === p.id ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'bg-white dark:bg-slate-800 text-slate-400 dark:text-slate-500 border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700'}`}>
                  {p.label.toUpperCase()}
                </button>
              ))}
              <button onClick={handleManualRefresh} disabled={isRefreshing} className="ml-auto flex items-center gap-2 px-3 py-1.5 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:text-blue-600 transition-all active:scale-95 disabled:opacity-50">
                <div className={isRefreshing ? 'animate-spin-slow' : ''}><Icons.Refresh /></div>
              </button>
            </div>
        </div>
      </div>

      {/* CARDS */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 md:gap-6">
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-indigo-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Processos Atribuídos</p>
          <h4 className="text-3xl md:text-4xl font-black text-indigo-600 dark:text-indigo-400 mt-1 md:mt-2">{filteredTasks.reduce((acc, t) => acc + (Number(t.assignedProcesses) || 0), 0)}</h4>
        </div>
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-blue-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Processos Realizados</p>
          <h4 className="text-3xl md:text-4xl font-black text-blue-600 dark:text-blue-500 mt-1 md:mt-2">{commonTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0)}</h4>
        </div>
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-emerald-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Notas Fiscais</p>
          <h4 className="text-3xl md:text-4xl font-black text-emerald-600 dark:text-emerald-400 mt-1 md:mt-2">{filteredTasks.reduce((acc, t) => acc + (Number(t.invoiceQuantity) || 0), 0)}</h4>
        </div>
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-amber-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Licitações / Diárias</p>
          <h4 className="text-3xl md:text-4xl font-black text-amber-600 dark:text-amber-500 mt-1 md:mt-2">{specialTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0)}</h4>
        </div>
      </div>

      {/* GRAFICOS */}
      <div className="space-y-8">
        {activeTab === 'common' ? (
          <>
            {/* Gráfico de Barras: Comparativo por Analista */}
            <div className="bg-white dark:bg-slate-900 p-6 md:p-10 rounded-[32px] md:rounded-[48px] shadow-sm border border-slate-200 dark:border-slate-800 transition-colors">
              <h3 className="text-xl md:text-2xl font-black text-slate-800 dark:text-slate-100 uppercase tracking-tight mb-8">Performance por Analista</h3>
              <div className="chart-container-lg">
                {barData.length > 0 ? (
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={barData} margin={{ top: 30, right: 10, left: -20, bottom: 20 }}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" className="dark:opacity-10" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={10} fontWeight={800} tick={{ fill: '#94a3b8' }} />
                      <YAxis axisLine={false} tickLine={false} fontSize={10} tick={{ fill: '#94a3b8' }} />
                      <Tooltip cursor={{fill: 'rgba(248, 250, 252, 0.05)'}} contentStyle={{ borderRadius: '12px', border: 'none', backgroundColor: '#1e293b', color: '#fff' }} />
                      <Legend verticalAlign="top" align="right" wrapperStyle={{ paddingBottom: '30px', fontSize: '10px' }} formatter={(value) => <span className="text-slate-500 dark:text-slate-400 font-bold uppercase">{value}</span>} />

                      <Bar dataKey="atribuidos" name="Atribuídos" fill="#6366f1" radius={[4, 4, 0, 0]} barSize={24} onClick={(data) => togglePerson(data.id)} style={{ cursor: 'pointer' }}>
                        <LabelList dataKey="atribuidos" position="top" style={{ fill: '#6366f1', fontSize: 10, fontWeight: 900 }} />
                        {barData.map((entry, index) => <Cell key={`c0-${index}`} fillOpacity={entry.opacity} />)}
                      </Bar>
                      <Bar dataKey="realizados" name="Realizados" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={24} onClick={(data) => togglePerson(data.id)} style={{ cursor: 'pointer' }}>
                        <LabelList dataKey="realizados" position="top" style={{ fill: '#3b82f6', fontSize: 10, fontWeight: 900 }} />
                        {barData.map((entry, index) => <Cell key={`c1-${index}`} fillOpacity={entry.opacity} />)}
                      </Bar>
                      <Bar dataKey="notas" name="Notas Fiscais" fill="#10b981" radius={[4, 4, 0, 0]} barSize={24} onClick={(data) => togglePerson(data.id)} style={{ cursor: 'pointer' }}>
                        <LabelList dataKey="notas" position="top" style={{ fill: '#10b981', fontSize: 10, fontWeight: 900 }} />
                        {barData.map((entry, index) => <Cell key={`c2-${index}`} fillOpacity={entry.opacity} />)}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                ) : <EmptyNotice msg="Nenhum registro encontrado." />}
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              {/* Gráfico de Tendência: Evolução de Realizados */}
              <div className="bg-white dark:bg-slate-900 p-6 md:p-10 rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800">
                <h3 className="text-lg md:text-xl font-black text-slate-800 dark:text-slate-100 mb-6 uppercase tracking-tight">Tendência de Produção</h3>
                <div className="chart-container-md h-[300px]">
                  {areaData.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={areaData} margin={{ top: 20, right: 10, left: -20, bottom: 0 }}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" className="dark:opacity-10" />
                        <XAxis dataKey="date" fontSize={9} stroke="#94a3b8" tickFormatter={(v) => v.split('-').slice(1).reverse().join('/')} />
                        <YAxis fontSize={9} stroke="#94a3b8" />
                        <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', backgroundColor: '#1e293b', color: '#fff' }} />
                        <Area type="monotone" dataKey="realizados" name="Realizados" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.1} strokeWidth={4}>
                           <LabelList dataKey="realizados" position="top" offset={10} style={{ fill: '#3b82f6', fontSize: 10, fontWeight: 900 }} />
                        </Area>
                      </AreaChart>
                    </ResponsiveContainer>
                  ) : <EmptyNotice msg="Sem histórico temporal." />}
                </div>
              </div>

              {/* Gráfico de Pizza: Tipos de Serviços */}
              <div className="bg-white dark:bg-slate-900 p-6 md:p-10 rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800">
                <h3 className="text-lg md:text-xl font-black text-slate-800 dark:text-slate-100 mb-6 uppercase tracking-tight">Distribuição de Serviços</h3>
                <div className="chart-container-md h-[300px]">
                  {pieData.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie
                          data={pieData}
                          cx="50%"
                          cy="50%"
                          labelLine={false}
                          outerRadius={100}
                          fill="#8884d8"
                          dataKey="value"
                          label={({ name, value, percent }) => `${name}: ${value}`}
                        >
                          {pieData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={PRESET_COLORS[index % PRESET_COLORS.length]} />
                          ))}
                        </Pie>
                        <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', backgroundColor: '#1e293b', color: '#fff' }} />
                      </PieChart>
                    </ResponsiveContainer>
                  ) : <EmptyNotice msg="Dados insuficientes para o gráfico." />}
                </div>
              </div>
            </div>
          </>
        ) : (
          /* Seção Licitação/Diária (Não mexer conforme solicitado, apenas renderizar se necessário) */
          <div className="bg-white dark:bg-slate-900 p-6 md:p-10 rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 transition-colors">
            <h3 className="text-xl md:text-2xl font-black text-slate-800 dark:text-slate-100 uppercase tracking-tight mb-8">Produtividade Licitação/Diária</h3>
             <div className="chart-container-lg">
                {specialTasks.length > 0 ? (
                  <p className="text-center p-20 font-bold text-slate-400">Dados de Licitação em análise...</p>
                ) : <EmptyNotice msg="Nenhum registro de Licitação/Diária." />}
             </div>
          </div>
        )}

        {/* Diagnóstico IA */}
        <div className="bg-slate-900 dark:bg-slate-800 rounded-[32px] p-8 text-white relative overflow-hidden flex flex-col justify-center">
          <div className="absolute top-0 right-0 p-10 opacity-10"><Icons.Sparkles /></div>
          <h2 className="text-xl font-black uppercase tracking-widest mb-2">Diagnóstico IA</h2>
          <p className="text-slate-400 text-sm mb-6">Análise inteligente de vazão (Atribuído vs Realizado).</p>
          {aiInsight ? (
            <div className="bg-white/5 p-5 rounded-2xl text-xs leading-relaxed max-h-[200px] overflow-y-auto custom-scrollbar">
              {aiInsight}
              <button onClick={() => setAiInsight(null)} className="block mt-4 text-[10px] font-black opacity-50 uppercase hover:opacity-100 transition-opacity">Limpar Análise</button>
            </div>
          ) : (
            <button onClick={handleGetInsights} disabled={loadingAi || filteredTasks.length === 0} className="bg-blue-600 px-6 py-4 rounded-xl font-black text-xs uppercase hover:bg-blue-700 transition-all flex items-center justify-center gap-2 w-fit">
              {loadingAi ? <div className="animate-spin w-4 h-4 border-2 border-white/20 border-t-white rounded-full"></div> : <Icons.Sparkles />}
              Gerar Insights Estratégicos
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, AreaChart, Area, LabelList
} from 'recharts';
import { AppState, Task, ServiceCategory } from '../types';
import { Icons, PRESET_COLORS } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
  onRefresh?: () => Promise<void>;
}

type TabType = 'common' | 'special';
type PeriodPreset = 'hoje' | 'semanal' | 'quinzenal' | 'mensal' | 'trimestral' | 'anual' | 'custom';

const Dashboard: React.FC<DashboardProps> = ({ state, onRefresh }) => {
  const getLocalDateStr = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset();
    const localDate = new Date(d.getTime() - (offset * 60 * 1000));
    return localDate.toISOString().split('T')[0];
  };

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>(getLocalDateStr());
  const [activePreset, setActivePreset] = useState<PeriodPreset>('mensal');
  const [selectedPeopleIds, setSelectedPeopleIds] = useState<string[]>([]);
  const [activeTab, setActiveTab] = useState<TabType>('common');
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  useEffect(() => {
    const now = new Date();
    let start = new Date();

    switch (activePreset) {
      case 'hoje': break;
      case 'semanal': start.setDate(now.getDate() - 7); break;
      case 'quinzenal': start.setDate(now.getDate() - 15); break;
      case 'mensal': start.setDate(now.getDate() - 30); break;
      case 'trimestral': start.setDate(now.getDate() - 90); break;
      case 'anual': start.setDate(now.getDate() - 365); break;
      case 'custom': return;
    }

    setStartDate(getLocalDateStr(start));
    setEndDate(getLocalDateStr(now));
  }, [activePreset]);

  const isSpecialCategory = (categoryId: string) => {
    const cat = state.serviceCategories.find(c => c.id === categoryId);
    if (!cat) return false;
    const name = cat.name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    return name.includes('licitacao') || name.includes('diaria') || name.includes('contrato');
  };

  const togglePerson = (id: string) => {
    setSelectedPeopleIds(prev => 
      prev.includes(id) ? prev.filter(pId => pId !== id) : [...prev, id]
    );
  };

  const handleManualRefresh = async () => {
    if (onRefresh) {
      setIsRefreshing(true);
      await onRefresh();
      setTimeout(() => setIsRefreshing(false), 600);
    }
  };

  const filteredTasks = useMemo(() => {
    const tasks = state.tasks || [];
    return tasks.filter(t => {
      const dateMatch = (!startDate || t.date >= startDate) && (!endDate || t.date <= endDate);
      const personMatch = selectedPeopleIds.length === 0 || selectedPeopleIds.includes(t.personId);
      return dateMatch && personMatch;
    });
  }, [state.tasks, startDate, endDate, selectedPeopleIds]);

  const commonTasks = filteredTasks.filter(t => !isSpecialCategory(t.serviceCategoryId));
  const specialTasks = filteredTasks.filter(t => isSpecialCategory(t.serviceCategoryId));

  // Gráfico de Barras: Atribuídos, Realizados e Notas por Analista
  const barData = useMemo(() => {
    const tasksToCalculate = commonTasks;
    return (state.people || []).map(person => {
      const pTasks = tasksToCalculate.filter(t => t.personId === person.id);
      const atribuidos = pTasks.reduce((acc, t) => acc + (Number(t.assignedProcesses) || 0), 0);
      const realizados = pTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0);
      const notas = pTasks.reduce((acc, t) => acc + (Number(t.invoiceQuantity) || 0), 0);

      return {
        id: person.id,
        name: person.name,
        atribuidos,
        realizados,
        notas,
        opacity: selectedPeopleIds.length === 0 || selectedPeopleIds.includes(person.id) ? 1 : 0.3
      };
    }).filter(d => d.atribuidos > 0 || d.realizados > 0 || d.notas > 0).sort((a, b) => b.realizados - a.realizados);
  }, [state.people, commonTasks, selectedPeopleIds]);

  // Gráfico de Tendência: Evolução Temporal de Realizados
  const areaData = useMemo(() => {
    const map: Record<string, any> = {};
    commonTasks.forEach(t => {
      if (!map[t.date]) map[t.date] = { date: t.date, realizados: 0 };
      map[t.date].realizados += (Number(t.processQuantity) || 0);
    });
    return Object.values(map)
      .sort((a: any, b: any) => a.date.localeCompare(b.date));
  }, [commonTasks]);

  // Gráfico de Pizza: Tipos de Serviços
  const pieData = useMemo(() => {
    const map: Record<string, number> = {};
    commonTasks.forEach(t => {
      const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
      const name = cat?.name || 'Outros';
      map[name] = (map[name] || 0) + (Number(t.processQuantity) || 0);
    });
    return Object.entries(map).map(([name, value]) => ({ name, value }));
  }, [commonTasks, state.serviceCategories]);

  const handleGetInsights = async () => {
    if (filteredTasks.length === 0) return;
    setLoadingAi(true);
    try {
      const insight = await getProductivityInsights(filteredTasks, state.people, state.serviceCategories);
      setAiInsight(insight);
    } catch (e) {
      setAiInsight("Erro ao gerar análise inteligente.");
    } finally {
      setLoadingAi(false);
    }
  };

  const presets: { id: PeriodPreset, label: string }[] = [
    { id: 'hoje', label: 'Hoje' },
    { id: 'semanal', label: 'Semanal' },
    { id: 'quinzenal', label: 'Quinzenal' },
    { id: 'mensal', label: 'Mensal' },
    { id: 'anual', label: 'Anual' },
    { id: 'custom', label: 'Personalizado' }
  ];

  const EmptyNotice = ({ msg }: { msg: string }) => (
    <div className="flex flex-col items-center justify-center h-full p-10 bg-slate-50 dark:bg-slate-800/50 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-[32px] text-slate-300 dark:text-slate-600 transition-colors">
      <div className="opacity-20"><Icons.Calendar /></div>
      <p className="mt-4 font-black text-[10px] uppercase tracking-widest text-slate-400 dark:text-slate-500 text-center">{msg}</p>
    </div>
  );

  return (
    <div className="space-y-8 pb-20 fade-in">
      {/* FILTROS */}
      <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[32px] md:rounded-[40px] shadow-sm border border-slate-200 dark:border-slate-800 space-y-6 md:space-y-8 transition-colors">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
          <div className="space-y-1">
            <h3 className="text-xl font-black text-slate-800 dark:text-slate-100 uppercase tracking-tight">Análise Gerencial</h3>
            <p className="text-xs text-slate-400 dark:text-slate-500 font-bold">Monitoramento de Atribuições e Realizações</p>
          </div>
          <div className="flex p-1 bg-slate-100 dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 overflow-x-auto custom-scrollbar">
            {[
              { id: 'common', label: 'PROCESSOS / ATRIBUIÇÕES' },
              { id: 'special', label: 'LICITAÇÃO / DIÁRIA' }
            ].map(tab => (
              <button 
                key={tab.id}
                onClick={() => setActiveTab(tab.id as TabType)}
                className={`px-4 md:px-6 py-2 md:py-2.5 rounded-xl text-[9px] md:text-[10px] font-black tracking-widest transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm border border-slate-200 dark:border-slate-600' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600 dark:hover:text-slate-300'}`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        <div className="pt-6 md:pt-8 border-t border-slate-100 dark:border-slate-800">
           <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
              <div className="flex flex-wrap gap-2">
                {presets.map(p => (
                  <button key={p.id} onClick={() => setActivePreset(p.id)} className={`px-3 md:px-4 py-2 rounded-xl text-[9px] md:text-[10px] font-black border transition-all ${activePreset === p.id ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'bg-white dark:bg-slate-800 text-slate-400 dark:text-slate-500 border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700'}`}>
                    {p.label.toUpperCase()}
                  </button>
                ))}
              </div>

              <div className="flex flex-wrap items-center gap-4 bg-slate-50/50 dark:bg-slate-800/50 p-3 rounded-2xl border border-slate-100 dark:border-slate-800">
                <div className="flex flex-col">
                  <span className="text-[8px] font-black text-slate-400 dark:text-slate-500 uppercase ml-1 mb-1">Data Inicial</span>
                  <input 
                    type="date" 
                    value={startDate} 
                    onChange={(e) => {
                      setStartDate(e.target.value);
                      setActivePreset('custom');
                    }}
                    className="bg-white dark:bg-slate-800 text-[11px] font-bold text-slate-700 dark:text-slate-200 outline-none border border-slate-200 dark:border-slate-700 rounded-lg px-2 py-1" 
                  />
                </div>
                <div className="flex flex-col">
                  <span className="text-[8px] font-black text-slate-400 dark:text-slate-500 uppercase ml-1 mb-1">Data Final</span>
                  <input 
                    type="date" 
                    value={endDate} 
                    onChange={(e) => {
                      setEndDate(e.target.value);
                      setActivePreset('custom');
                    }}
                    className="bg-white dark:bg-slate-800 text-[11px] font-bold text-slate-700 dark:text-slate-200 outline-none border border-slate-200 dark:border-slate-700 rounded-lg px-2 py-1" 
                  />
                </div>
                <button onClick={handleManualRefresh} disabled={isRefreshing} className="flex items-center gap-2 p-2 rounded-xl bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:text-blue-600 transition-all active:scale-95 disabled:opacity-50">
                  <div className={isRefreshing ? 'animate-spin-slow' : ''}><Icons.Refresh /></div>
                </button>
              </div>
            </div>
        </div>
      </div>

      {/* CARDS */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 md:gap-6">
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-indigo-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Processos Atribuídos</p>
          <h4 className="text-3xl md:text-4xl font-black text-indigo-600 dark:text-indigo-400 mt-1 md:mt-2">{filteredTasks.reduce((acc, t) => acc + (Number(t.assignedProcesses) || 0), 0)}</h4>
        </div>
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-blue-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Processos Realizados</p>
          <h4 className="text-3xl md:text-4xl font-black text-blue-600 dark:text-blue-500 mt-1 md:mt-2">{commonTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0)}</h4>
        </div>
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-emerald-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Notas Fiscais</p>
          <h4 className="text-3xl md:text-4xl font-black text-emerald-600 dark:text-emerald-400 mt-1 md:mt-2">{filteredTasks.reduce((acc, t) => acc + (Number(t.invoiceQuantity) || 0), 0)}</h4>
        </div>
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-amber-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Licitações / Diárias</p>
          <h4 className="text-3xl md:text-4xl font-black text-amber-600 dark:text-amber-500 mt-1 md:mt-2">{specialTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0)}</h4>
        </div>
      </div>

      {/* GRAFICOS */}
      <div className="space-y-8">
        {activeTab === 'common' ? (
          <>
            {/* Gráfico de Barras: Comparativo por Analista */}
            <div className="bg-white dark:bg-slate-900 p-6 md:p-10 rounded-[32px] md:rounded-[48px] shadow-sm border border-slate-200 dark:border-slate-800 transition-colors">
              <h3 className="text-xl md:text-2xl font-black text-slate-800 dark:text-slate-100 uppercase tracking-tight mb-8">Performance por Analista</h3>
              <div className="chart-container-lg">
                {barData.length > 0 ? (
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={barData} margin={{ top: 30, right: 10, left: -20, bottom: 20 }}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" className="dark:opacity-10" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={10} fontWeight={800} tick={{ fill: '#94a3b8' }} />
                      <YAxis axisLine={false} tickLine={false} fontSize={10} tick={{ fill: '#94a3b8' }} />
                      <Tooltip cursor={{fill: 'rgba(248, 250, 252, 0.05)'}} contentStyle={{ borderRadius: '12px', border: 'none', backgroundColor: '#1e293b', color: '#fff' }} />
                      <Legend verticalAlign="top" align="right" wrapperStyle={{ paddingBottom: '30px', fontSize: '10px' }} formatter={(value) => <span className="text-slate-500 dark:text-slate-400 font-bold uppercase">{value}</span>} />

                      <Bar dataKey="atribuidos" name="Atribuídos" fill="#6366f1" radius={[4, 4, 0, 0]} barSize={24} onClick={(data) => togglePerson(data.id)} style={{ cursor: 'pointer' }}>
                        <LabelList dataKey="atribuidos" position="top" style={{ fill: '#6366f1', fontSize: 10, fontWeight: 900 }} />
                        {barData.map((entry, index) => <Cell key={`c0-${index}`} fillOpacity={entry.opacity} />)}
                      </Bar>
                      <Bar dataKey="realizados" name="Realizados" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={24} onClick={(data) => togglePerson(data.id)} style={{ cursor: 'pointer' }}>
                        <LabelList dataKey="realizados" position="top" style={{ fill: '#3b82f6', fontSize: 10, fontWeight: 900 }} />
                        {barData.map((entry, index) => <Cell key={`c1-${index}`} fillOpacity={entry.opacity} />)}
                      </Bar>
                      <Bar dataKey="notas" name="Notas Fiscais" fill="#10b981" radius={[4, 4, 0, 0]} barSize={24} onClick={(data) => togglePerson(data.id)} style={{ cursor: 'pointer' }}>
                        <LabelList dataKey="notas" position="top" style={{ fill: '#10b981', fontSize: 10, fontWeight: 900 }} />
                        {barData.map((entry, index) => <Cell key={`c2-${index}`} fillOpacity={entry.opacity} />)}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                ) : <EmptyNotice msg="Nenhum registro encontrado." />}
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              {/* Gráfico de Tendência: Evolução de Realizados */}
              <div className="bg-white dark:bg-slate-900 p-6 md:p-10 rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800">
                <h3 className="text-lg md:text-xl font-black text-slate-800 dark:text-slate-100 mb-6 uppercase tracking-tight">Tendência de Produção</h3>
                <div className="chart-container-md h-[300px]">
                  {areaData.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={areaData} margin={{ top: 20, right: 10, left: -20, bottom: 0 }}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" className="dark:opacity-10" />
                        <XAxis dataKey="date" fontSize={9} stroke="#94a3b8" tickFormatter={(v) => v.split('-').slice(1).reverse().join('/')} />
                        <YAxis fontSize={9} stroke="#94a3b8" />
                        <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', backgroundColor: '#1e293b', color: '#fff' }} />
                        <Area type="monotone" dataKey="realizados" name="Realizados" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.1} strokeWidth={4}>
                           <LabelList dataKey="realizados" position="top" offset={10} style={{ fill: '#3b82f6', fontSize: 10, fontWeight: 900 }} />
                        </Area>
                      </AreaChart>
                    </ResponsiveContainer>
                  ) : <EmptyNotice msg="Sem histórico temporal." />}
                </div>
              </div>

              {/* Gráfico de Pizza: Tipos de Serviços */}
              <div className="bg-white dark:bg-slate-900 p-6 md:p-10 rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800">
                <h3 className="text-lg md:text-xl font-black text-slate-800 dark:text-slate-100 mb-6 uppercase tracking-tight">Distribuição de Serviços</h3>
                <div className="chart-container-md h-[300px]">
                  {pieData.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie
                          data={pieData}
                          cx="50%"
                          cy="50%"
                          labelLine={false}
                          outerRadius={100}
                          fill="#8884d8"
                          dataKey="value"
                          label={({ name, value, percent }) => `${name}: ${value}`}
                        >
                          {pieData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={PRESET_COLORS[index % PRESET_COLORS.length]} />
                          ))}
                        </Pie>
                        <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', backgroundColor: '#1e293b', color: '#fff' }} />
                      </PieChart>
                    </ResponsiveContainer>
                  ) : <EmptyNotice msg="Dados insuficientes para o gráfico." />}
                </div>
              </div>
            </div>
          </>
        ) : (
          /* Seção Licitação/Diária (Não mexer conforme solicitado, apenas renderizar se necessário) */
          <div className="bg-white dark:bg-slate-900 p-6 md:p-10 rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 transition-colors">
            <h3 className="text-xl md:text-2xl font-black text-slate-800 dark:text-slate-100 uppercase tracking-tight mb-8">Produtividade Licitação/Diária</h3>
             <div className="chart-container-lg">
                {specialTasks.length > 0 ? (
                  <p className="text-center p-20 font-bold text-slate-400">Dados de Licitação em análise...</p>
                ) : <EmptyNotice msg="Nenhum registro de Licitação/Diária." />}
             </div>
          </div>
        )}

        {/* Diagnóstico IA */}
        <div className="bg-slate-900 dark:bg-slate-800 rounded-[32px] p-8 text-white relative overflow-hidden flex flex-col justify-center">
          <div className="absolute top-0 right-0 p-10 opacity-10"><Icons.Sparkles /></div>
          <h2 className="text-xl font-black uppercase tracking-widest mb-2">Diagnóstico IA</h2>
          <p className="text-slate-400 text-sm mb-6">Análise inteligente de vazão (Atribuído vs Realizado).</p>
          {aiInsight ? (
            <div className="bg-white/5 p-5 rounded-2xl text-xs leading-relaxed max-h-[200px] overflow-y-auto custom-scrollbar">
              {aiInsight}
              <button onClick={() => setAiInsight(null)} className="block mt-4 text-[10px] font-black opacity-50 uppercase hover:opacity-100 transition-opacity">Limpar Análise</button>
            </div>
          ) : (
            <button onClick={handleGetInsights} disabled={loadingAi || filteredTasks.length === 0} className="bg-blue-600 px-6 py-4 rounded-xl font-black text-xs uppercase hover:bg-blue-700 transition-all flex items-center justify-center gap-2 w-fit">
              {loadingAi ? <div className="animate-spin w-4 h-4 border-2 border-white/20 border-t-white rounded-full"></div> : <Icons.Sparkles />}
              Gerar Insights Estratégicos
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, AreaChart, Area, LabelList
} from 'recharts';
import { AppState, Task, ServiceCategory } from '../types';
import { Icons, PRESET_COLORS } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
  onRefresh?: () => Promise<void>;
}

type TabType = 'common' | 'special';
type PeriodPreset = 'hoje' | 'semanal' | 'quinzenal' | 'mensal' | 'trimestral' | 'anual' | 'custom';

const Dashboard: React.FC<DashboardProps> = ({ state, onRefresh }) => {
  const getLocalDateStr = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset();
    const localDate = new Date(d.getTime() - (offset * 60 * 1000));
    return localDate.toISOString().split('T')[0];
  };

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>(getLocalDateStr());
  const [activePreset, setActivePreset] = useState<PeriodPreset>('mensal');
  const [selectedPeopleIds, setSelectedPeopleIds] = useState<string[]>([]);
  const [activeTab, setActiveTab] = useState<TabType>('common');
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  useEffect(() => {
    const now = new Date();
    let start = new Date();

    switch (activePreset) {
      case 'hoje': break;
      case 'semanal': start.setDate(now.getDate() - 7); break;
      case 'quinzenal': start.setDate(now.getDate() - 15); break;
      case 'mensal': start.setDate(now.getDate() - 30); break;
      case 'trimestral': start.setDate(now.getDate() - 90); break;
      case 'anual': start.setDate(now.getDate() - 365); break;
      case 'custom': return;
    }

    setStartDate(getLocalDateStr(start));
    setEndDate(getLocalDateStr(now));
  }, [activePreset]);

  const isSpecialCategory = (categoryId: string) => {
    const cat = state.serviceCategories.find(c => c.id === categoryId);
    if (!cat) return false;
    const name = cat.name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    return name.includes('licitacao') || name.includes('diaria') || name.includes('contrato');
  };

  const togglePerson = (id: string) => {
    setSelectedPeopleIds(prev => 
      prev.includes(id) ? prev.filter(pId => pId !== id) : [...prev, id]
    );
  };

  const clearPeopleFilter = () => setSelectedPeopleIds([]);

  const handleManualRefresh = async () => {
    if (onRefresh) {
      setIsRefreshing(true);
      await onRefresh();
      setTimeout(() => setIsRefreshing(false), 600);
    }
  };

  // filteredTasks para os Cards e Gráfico de Barras (sempre mostra contexto temporal)
  const tasksByDate = useMemo(() => {
    return (state.tasks || []).filter(t => {
      return (!startDate || t.date >= startDate) && (!endDate || t.date <= endDate);
    });
  }, [state.tasks, startDate, endDate]);

  // filteredTasks para Gráficos de Tendência e Pizza (respeita o filtro de colaborador)
  const tasksForDetailedCharts = useMemo(() => {
    return tasksByDate.filter(t => {
      return selectedPeopleIds.length === 0 || selectedPeopleIds.includes(t.personId);
    });
  }, [tasksByDate, selectedPeopleIds]);

  const commonTasksDetailed = tasksForDetailedCharts.filter(t => !isSpecialCategory(t.serviceCategoryId));
  const specialTasksDetailed = tasksForDetailedCharts.filter(t => isSpecialCategory(t.serviceCategoryId));

  // Gráfico de Barras: Sempre mostra todos os analistas do período, mas destaca os selecionados
  const barData = useMemo(() => {
    return (state.people || []).map(person => {
      const pTasks = tasksByDate.filter(t => t.personId === person.id && !isSpecialCategory(t.serviceCategoryId));
      const atribuidos = pTasks.reduce((acc, t) => acc + (Number(t.assignedProcesses) || 0), 0);
      const realizados = pTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0);
      const notas = pTasks.reduce((acc, t) => acc + (Number(t.invoiceQuantity) || 0), 0);

      const isSelected = selectedPeopleIds.length === 0 || selectedPeopleIds.includes(person.id);

      return {
        id: person.id,
        name: person.name,
        atribuidos,
        realizados,
        notas,
        opacity: isSelected ? 1 : 0.15
      };
    }).filter(d => d.atribuidos > 0 || d.realizados > 0 || d.notas > 0).sort((a, b) => b.realizados - a.realizados);
  }, [state.people, tasksByDate, selectedPeopleIds]);

  // Gráfico de Tendência: Evolução Temporal de Realizados
  const areaData = useMemo(() => {
    const map: Record<string, any> = {};
    commonTasksDetailed.forEach(t => {
      if (!map[t.date]) map[t.date] = { date: t.date, realizados: 0 };
      map[t.date].realizados += (Number(t.processQuantity) || 0);
    });
    return Object.values(map)
      .sort((a: any, b: any) => a.date.localeCompare(b.date));
  }, [commonTasksDetailed]);

  // Gráfico de Pizza: Tipos de Serviços
  const pieData = useMemo(() => {
    const map: Record<string, number> = {};
    commonTasksDetailed.forEach(t => {
      const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
      const name = cat?.name || 'Outros';
      map[name] = (map[name] || 0) + (Number(t.processQuantity) || 0);
    });
    return Object.entries(map).map(([name, value]) => ({ name, value }));
  }, [commonTasksDetailed, state.serviceCategories]);

  const handleGetInsights = async () => {
    if (tasksForDetailedCharts.length === 0) return;
    setLoadingAi(true);
    try {
      const insight = await getProductivityInsights(tasksForDetailedCharts, state.people, state.serviceCategories);
      setAiInsight(insight);
    } catch (e) {
      setAiInsight("Erro ao gerar análise inteligente.");
    } finally {
      setLoadingAi(false);
    }
  };

  const presets: { id: PeriodPreset, label: string }[] = [
    { id: 'hoje', label: 'Hoje' },
    { id: 'semanal', label: 'Semanal' },
    { id: 'quinzenal', label: 'Quinzenal' },
    { id: 'mensal', label: 'Mensal' },
    { id: 'anual', label: 'Anual' },
    { id: 'custom', label: 'Personalizado' }
  ];

  const EmptyNotice = ({ msg }: { msg: string }) => (
    <div className="flex flex-col items-center justify-center h-full p-10 bg-slate-50 dark:bg-slate-800/50 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-[32px] text-slate-300 dark:text-slate-600 transition-colors">
      <div className="opacity-20"><Icons.Calendar /></div>
      <p className="mt-4 font-black text-[10px] uppercase tracking-widest text-slate-400 dark:text-slate-500 text-center">{msg}</p>
    </div>
  );

  return (
    <div className="space-y-8 pb-20 fade-in">
      {/* FILTROS PRINCIPAIS */}
      <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[32px] md:rounded-[40px] shadow-sm border border-slate-200 dark:border-slate-800 space-y-6 md:space-y-8 transition-colors">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
          <div className="space-y-1">
            <h3 className="text-xl font-black text-slate-800 dark:text-slate-100 uppercase tracking-tight">Análise Gerencial</h3>
            <p className="text-xs text-slate-400 dark:text-slate-500 font-bold">Monitoramento de Atribuições e Realizações</p>
          </div>
          <div className="flex p-1 bg-slate-100 dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 overflow-x-auto custom-scrollbar">
            {[
              { id: 'common', label: 'PROCESSOS / ATRIBUIÇÕES' },
              { id: 'special', label: 'LICITAÇÃO / DIÁRIA' }
            ].map(tab => (
              <button 
                key={tab.id}
                onClick={() => setActiveTab(tab.id as TabType)}
                className={`px-4 md:px-6 py-2 md:py-2.5 rounded-xl text-[9px] md:text-[10px] font-black tracking-widest transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm border border-slate-200 dark:border-slate-600' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600 dark:hover:text-slate-300'}`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        <div className="pt-6 md:pt-8 border-t border-slate-100 dark:border-slate-800 space-y-6">
           {/* Período */}
           <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
              <div className="flex flex-wrap gap-2">
                {presets.map(p => (
                  <button key={p.id} onClick={() => setActivePreset(p.id)} className={`px-3 md:px-4 py-2 rounded-xl text-[9px] md:text-[10px] font-black border transition-all ${activePreset === p.id ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'bg-white dark:bg-slate-800 text-slate-400 dark:text-slate-500 border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700'}`}>
                    {p.label.toUpperCase()}
                  </button>
                ))}
              </div>

              <div className="flex flex-wrap items-center gap-4 bg-slate-50/50 dark:bg-slate-800/50 p-3 rounded-2xl border border-slate-100 dark:border-slate-800">
                <div className="flex flex-col">
                  <span className="text-[8px] font-black text-slate-400 dark:text-slate-500 uppercase ml-1 mb-1">Início</span>
                  <input 
                    type="date" 
                    value={startDate} 
                    onChange={(e) => {
                      setStartDate(e.target.value);
                      setActivePreset('custom');
                    }}
                    className="bg-white dark:bg-slate-800 text-[11px] font-bold text-slate-700 dark:text-slate-200 outline-none border border-slate-200 dark:border-slate-700 rounded-lg px-2 py-1" 
                  />
                </div>
                <div className="flex flex-col">
                  <span className="text-[8px] font-black text-slate-400 dark:text-slate-500 uppercase ml-1 mb-1">Fim</span>
                  <input 
                    type="date" 
                    value={endDate} 
                    onChange={(e) => {
                      setEndDate(e.target.value);
                      setActivePreset('custom');
                    }}
                    className="bg-white dark:bg-slate-800 text-[11px] font-bold text-slate-700 dark:text-slate-200 outline-none border border-slate-200 dark:border-slate-700 rounded-lg px-2 py-1" 
                  />
                </div>
                <button onClick={handleManualRefresh} disabled={isRefreshing} className="flex items-center gap-2 p-2 rounded-xl bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:text-blue-600 transition-all active:scale-95 disabled:opacity-50">
                  <div className={isRefreshing ? 'animate-spin-slow' : ''}><Icons.Refresh /></div>
                </button>
              </div>
            </div>

            {/* Filtro Colaborador */}
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <Icons.People /> Filtrar por Colaborador
                </span>
                {selectedPeopleIds.length > 0 && (
                  <button onClick={clearPeopleFilter} className="text-[10px] font-black text-blue-600 dark:text-blue-400 hover:underline">LIMPAR FILTRO</button>
                )}
              </div>
              <div className="flex flex-wrap gap-2">
                {state.people.map(person => {
                  const isSelected = selectedPeopleIds.includes(person.id);
                  return (
                    <button
                      key={person.id}
                      onClick={() => togglePerson(person.id)}
                      className={`px-3 py-1.5 rounded-full text-[10px] font-bold transition-all border ${
                        isSelected 
                          ? 'bg-blue-100 border-blue-200 text-blue-700 dark:bg-blue-900/40 dark:border-blue-800 dark:text-blue-300 ring-2 ring-blue-500/20' 
                          : 'bg-slate-50 border-slate-100 text-slate-500 dark:bg-slate-800/50 dark:border-slate-800 dark:text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'
                      }`}
                    >
                      {person.name}
                    </button>
                  );
                })}
              </div>
            </div>
        </div>
      </div>

      {/* CARDS */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 md:gap-6">
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-indigo-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Processos Atribuídos</p>
          <h4 className="text-3xl md:text-4xl font-black text-indigo-600 dark:text-indigo-400 mt-1 md:mt-2">{tasksForDetailedCharts.reduce((acc, t) => acc + (Number(t.assignedProcesses) || 0), 0)}</h4>
        </div>
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-blue-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Processos Realizados</p>
          <h4 className="text-3xl md:text-4xl font-black text-blue-600 dark:text-blue-500 mt-1 md:mt-2">{commonTasksDetailed.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0)}</h4>
        </div>
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-emerald-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Notas Fiscais</p>
          <h4 className="text-3xl md:text-4xl font-black text-emerald-600 dark:text-emerald-400 mt-1 md:mt-2">{tasksForDetailedCharts.reduce((acc, t) => acc + (Number(t.invoiceQuantity) || 0), 0)}</h4>
        </div>
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-amber-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Licitações / Diárias</p>
          <h4 className="text-3xl md:text-4xl font-black text-amber-600 dark:text-amber-500 mt-1 md:mt-2">{specialTasksDetailed.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0)}</h4>
        </div>
      </div>

      {/* GRAFICOS */}
      <div className="space-y-8">
        {activeTab === 'common' ? (
          <>
            {/* Gráfico de Barras: Comparativo por Analista */}
            <div className="bg-white dark:bg-slate-900 p-6 md:p-10 rounded-[32px] md:rounded-[48px] shadow-sm border border-slate-200 dark:border-slate-800 transition-colors">
              <div className="flex items-center justify-between mb-8">
                <h3 className="text-xl md:text-2xl font-black text-slate-800 dark:text-slate-100 uppercase tracking-tight">Performance por Analista</h3>
                <span className="text-[9px] font-black text-slate-400 uppercase bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-full">Clique na barra para filtrar</span>
              </div>
              <div className="chart-container-lg">
                {barData.length > 0 ? (
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={barData} margin={{ top: 30, right: 10, left: -20, bottom: 20 }}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" className="dark:opacity-10" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={10} fontWeight={800} tick={{ fill: '#94a3b8' }} />
                      <YAxis axisLine={false} tickLine={false} fontSize={10} tick={{ fill: '#94a3b8' }} />
                      <Tooltip cursor={{fill: 'rgba(248, 250, 252, 0.05)'}} contentStyle={{ borderRadius: '12px', border: 'none', backgroundColor: '#1e293b', color: '#fff' }} />
                      <Legend verticalAlign="top" align="right" wrapperStyle={{ paddingBottom: '30px', fontSize: '10px' }} formatter={(value) => <span className="text-slate-500 dark:text-slate-400 font-bold uppercase">{value}</span>} />

                      <Bar dataKey="atribuidos" name="Atribuídos" fill="#6366f1" radius={[4, 4, 0, 0]} barSize={24} onClick={(data) => togglePerson(data.id)} style={{ cursor: 'pointer' }}>
                        <LabelList dataKey="atribuidos" position="top" style={{ fill: '#6366f1', fontSize: 10, fontWeight: 900 }} />
                        {barData.map((entry, index) => <Cell key={`c0-${index}`} fillOpacity={entry.opacity} />)}
                      </Bar>
                      <Bar dataKey="realizados" name="Realizados" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={24} onClick={(data) => togglePerson(data.id)} style={{ cursor: 'pointer' }}>
                        <LabelList dataKey="realizados" position="top" style={{ fill: '#3b82f6', fontSize: 10, fontWeight: 900 }} />
                        {barData.map((entry, index) => <Cell key={`c1-${index}`} fillOpacity={entry.opacity} />)}
                      </Bar>
                      <Bar dataKey="notas" name="Notas Fiscais" fill="#10b981" radius={[4, 4, 0, 0]} barSize={24} onClick={(data) => togglePerson(data.id)} style={{ cursor: 'pointer' }}>
                        <LabelList dataKey="notas" position="top" style={{ fill: '#10b981', fontSize: 10, fontWeight: 900 }} />
                        {barData.map((entry, index) => <Cell key={`c2-${index}`} fillOpacity={entry.opacity} />)}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                ) : <EmptyNotice msg="Nenhum registro encontrado." />}
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              {/* Gráfico de Tendência: Evolução de Realizados */}
              <div className="bg-white dark:bg-slate-900 p-6 md:p-10 rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800">
                <h3 className="text-lg md:text-xl font-black text-slate-800 dark:text-slate-100 mb-6 uppercase tracking-tight">Tendência de Produção {selectedPeopleIds.length > 0 && <span className="text-blue-500 text-xs ml-2">(Filtrado)</span>}</h3>
                <div className="chart-container-md h-[300px]">
                  {areaData.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={areaData} margin={{ top: 20, right: 10, left: -20, bottom: 0 }}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" className="dark:opacity-10" />
                        <XAxis dataKey="date" fontSize={9} stroke="#94a3b8" tickFormatter={(v) => v.split('-').slice(1).reverse().join('/')} />
                        <YAxis fontSize={9} stroke="#94a3b8" />
                        <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', backgroundColor: '#1e293b', color: '#fff' }} />
                        <Area type="monotone" dataKey="realizados" name="Realizados" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.1} strokeWidth={4}>
                           <LabelList dataKey="realizados" position="top" offset={10} style={{ fill: '#3b82f6', fontSize: 10, fontWeight: 900 }} />
                        </Area>
                      </AreaChart>
                    </ResponsiveContainer>
                  ) : <EmptyNotice msg="Sem histórico temporal para este filtro." />}
                </div>
              </div>

              {/* Gráfico de Pizza: Tipos de Serviços */}
              <div className="bg-white dark:bg-slate-900 p-6 md:p-10 rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800">
                <h3 className="text-lg md:text-xl font-black text-slate-800 dark:text-slate-100 mb-6 uppercase tracking-tight">Distribuição de Serviços {selectedPeopleIds.length > 0 && <span className="text-blue-500 text-xs ml-2">(Filtrado)</span>}</h3>
                <div className="chart-container-md h-[300px]">
                  {pieData.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie
                          data={pieData}
                          cx="50%"
                          cy="50%"
                          labelLine={false}
                          outerRadius={100}
                          fill="#8884d8"
                          dataKey="value"
                          label={({ name, value, percent }) => `${name}: ${value}`}
                        >
                          {pieData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={PRESET_COLORS[index % PRESET_COLORS.length]} />
                          ))}
                        </Pie>
                        <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', backgroundColor: '#1e293b', color: '#fff' }} />
                      </PieChart>
                    </ResponsiveContainer>
                  ) : <EmptyNotice msg="Dados insuficientes para o gráfico." />}
                </div>
              </div>
            </div>
          </>
        ) : (
          /* Seção Licitação/Diária */
          <div className="bg-white dark:bg-slate-900 p-6 md:p-10 rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 transition-colors">
            <h3 className="text-xl md:text-2xl font-black text-slate-800 dark:text-slate-100 uppercase tracking-tight mb-8">Produtividade Licitação/Diária {selectedPeopleIds.length > 0 && <span className="text-blue-500 text-xs ml-2">(Filtrado)</span>}</h3>
             <div className="chart-container-lg">
                {specialTasksDetailed.length > 0 ? (
                   <div className="flex flex-col items-center justify-center h-full space-y-4">
                      <div className="text-6xl font-black text-slate-200 dark:text-slate-800">{specialTasksDetailed.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0)}</div>
                      <p className="font-bold text-slate-400 uppercase tracking-widest text-xs">Total de Realizações no Período Selecionado</p>
                   </div>
                ) : <EmptyNotice msg="Nenhum registro de Licitação/Diária para este filtro." />}
             </div>
          </div>
        )}

        {/* Diagnóstico IA */}
        <div className="bg-slate-900 dark:bg-slate-800 rounded-[32px] p-8 text-white relative overflow-hidden flex flex-col justify-center">
          <div className="absolute top-0 right-0 p-10 opacity-10"><Icons.Sparkles /></div>
          <h2 className="text-xl font-black uppercase tracking-widest mb-2">Diagnóstico IA</h2>
          <p className="text-slate-400 text-sm mb-6">Análise inteligente de vazão baseada nos filtros atuais.</p>
          {aiInsight ? (
            <div className="bg-white/5 p-5 rounded-2xl text-xs leading-relaxed max-h-[200px] overflow-y-auto custom-scrollbar">
              {aiInsight}
              <button onClick={() => setAiInsight(null)} className="block mt-4 text-[10px] font-black opacity-50 uppercase hover:opacity-100 transition-opacity">Limpar Análise</button>
            </div>
          ) : (
            <button onClick={handleGetInsights} disabled={loadingAi || tasksForDetailedCharts.length === 0} className="bg-blue-600 px-6 py-4 rounded-xl font-black text-xs uppercase hover:bg-blue-700 transition-all flex items-center justify-center gap-2 w-fit">
              {loadingAi ? <div className="animate-spin w-4 h-4 border-2 border-white/20 border-t-white rounded-full"></div> : <Icons.Sparkles />}
              Gerar Insights Estratégicos
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, AreaChart, Area, LabelList
} from 'recharts';
import { AppState, Task, ServiceCategory } from '../types';
import { Icons, PRESET_COLORS } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
  onRefresh?: () => Promise<void>;
}

type TabType = 'common' | 'special';
type PeriodPreset = 'hoje' | 'semanal' | 'quinzenal' | 'mensal' | 'trimestral' | 'anual' | 'custom';

const Dashboard: React.FC<DashboardProps> = ({ state, onRefresh }) => {
  const getLocalDateStr = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset();
    const localDate = new Date(d.getTime() - (offset * 60 * 1000));
    return localDate.toISOString().split('T')[0];
  };

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>(getLocalDateStr());
  const [activePreset, setActivePreset] = useState<PeriodPreset>('mensal');
  const [selectedPeopleIds, setSelectedPeopleIds] = useState<string[]>([]);
  const [activeTab, setActiveTab] = useState<TabType>('common');
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  useEffect(() => {
    const now = new Date();
    let start = new Date();

    switch (activePreset) {
      case 'hoje': break;
      case 'semanal': start.setDate(now.getDate() - 7); break;
      case 'quinzenal': start.setDate(now.getDate() - 15); break;
      case 'mensal': start.setDate(now.getDate() - 30); break;
      case 'trimestral': start.setDate(now.getDate() - 90); break;
      case 'anual': start.setDate(now.getDate() - 365); break;
      case 'custom': return;
    }

    setStartDate(getLocalDateStr(start));
    setEndDate(getLocalDateStr(now));
  }, [activePreset]);

  const isSpecialCategory = (categoryId: string) => {
    const cat = state.serviceCategories.find(c => c.id === categoryId);
    if (!cat) return false;
    const name = cat.name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    return name.includes('licitacao') || name.includes('diaria') || name.includes('contrato');
  };

  const togglePerson = (id: string) => {
    setSelectedPeopleIds(prev => 
      prev.includes(id) ? prev.filter(pId => pId !== id) : [...prev, id]
    );
  };

  const clearPeopleFilter = () => setSelectedPeopleIds([]);

  const handleManualRefresh = async () => {
    if (onRefresh) {
      setIsRefreshing(true);
      await onRefresh();
      setTimeout(() => setIsRefreshing(false), 600);
    }
  };

  const tasksByDate = useMemo(() => {
    return (state.tasks || []).filter(t => {
      return (!startDate || t.date >= startDate) && (!endDate || t.date <= endDate);
    });
  }, [state.tasks, startDate, endDate]);

  const tasksForDetailedCharts = useMemo(() => {
    return tasksByDate.filter(t => {
      return selectedPeopleIds.length === 0 || selectedPeopleIds.includes(t.personId);
    });
  }, [tasksByDate, selectedPeopleIds]);

  // Funções de processamento de dados para gráficos
  const processBarData = (tasks: Task[], onlySpecial: boolean) => {
    return (state.people || []).map(person => {
      const pTasks = tasks.filter(t => t.personId === person.id && isSpecialCategory(t.serviceCategoryId) === onlySpecial);
      const atribuidos = pTasks.reduce((acc, t) => acc + (Number(t.assignedProcesses) || 0), 0);
      const realizados = pTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0);
      const notas = pTasks.reduce((acc, t) => acc + (Number(t.invoiceQuantity) || 0), 0);
      const isSelected = selectedPeopleIds.length === 0 || selectedPeopleIds.includes(person.id);
      return { id: person.id, name: person.name, atribuidos, realizados, notas, opacity: isSelected ? 1 : 0.15 };
    }).filter(d => d.atribuidos > 0 || d.realizados > 0 || d.notas > 0).sort((a, b) => b.realizados - a.realizados);
  };

  const processAreaData = (tasks: Task[], onlySpecial: boolean) => {
    const map: Record<string, any> = {};
    tasks.filter(t => isSpecialCategory(t.serviceCategoryId) === onlySpecial).forEach(t => {
      if (!map[t.date]) map[t.date] = { date: t.date, realizados: 0 };
      map[t.date].realizados += (Number(t.processQuantity) || 0);
    });
    return Object.values(map).sort((a: any, b: any) => a.date.localeCompare(b.date));
  };

  const processPieData = (tasks: Task[], onlySpecial: boolean) => {
    const map: Record<string, number> = {};
    tasks.filter(t => isSpecialCategory(t.serviceCategoryId) === onlySpecial).forEach(t => {
      const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
      const name = cat?.name || 'Outros';
      map[name] = (map[name] || 0) + (Number(t.processQuantity) || 0);
    });
    return Object.entries(map).map(([name, value]) => ({ name, value }));
  };

  const commonBarData = useMemo(() => processBarData(tasksByDate, false), [state.people, tasksByDate, selectedPeopleIds]);
  const specialBarData = useMemo(() => processBarData(tasksByDate, true), [state.people, tasksByDate, selectedPeopleIds]);

  const commonAreaData = useMemo(() => processAreaData(tasksForDetailedCharts, false), [tasksForDetailedCharts]);
  const specialAreaData = useMemo(() => processAreaData(tasksForDetailedCharts, true), [tasksForDetailedCharts]);

  const commonPieData = useMemo(() => processPieData(tasksForDetailedCharts, false), [tasksForDetailedCharts, state.serviceCategories]);
  const specialPieData = useMemo(() => processPieData(tasksForDetailedCharts, true), [tasksForDetailedCharts, state.serviceCategories]);

  const handleGetInsights = async () => {
    if (tasksForDetailedCharts.length === 0) return;
    setLoadingAi(true);
    try {
      const insight = await getProductivityInsights(tasksForDetailedCharts, state.people, state.serviceCategories);
      setAiInsight(insight);
    } catch (e) {
      setAiInsight("Erro ao gerar análise inteligente.");
    } finally {
      setLoadingAi(false);
    }
  };

  const presets: { id: PeriodPreset, label: string }[] = [
    { id: 'hoje', label: 'Hoje' },
    { id: 'semanal', label: 'Semanal' },
    { id: 'quinzenal', label: 'Quinzenal' },
    { id: 'mensal', label: 'Mensal' },
    { id: 'anual', label: 'Anual' },
    { id: 'custom', label: 'Personalizado' }
  ];

  const EmptyNotice = ({ msg }: { msg: string }) => (
    <div className="flex flex-col items-center justify-center h-full p-10 bg-slate-50 dark:bg-slate-800/50 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-[32px] text-slate-300 dark:text-slate-600 transition-colors">
      <div className="opacity-20"><Icons.Calendar /></div>
      <p className="mt-4 font-black text-[10px] uppercase tracking-widest text-slate-400 dark:text-slate-500 text-center">{msg}</p>
    </div>
  );

  const currentBarData = activeTab === 'common' ? commonBarData : specialBarData;
  const currentAreaData = activeTab === 'common' ? commonAreaData : specialAreaData;
  const currentPieData = activeTab === 'common' ? commonPieData : specialPieData;

  return (
    <div className="space-y-8 pb-20 fade-in">
      {/* FILTROS PRINCIPAIS */}
      <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[32px] md:rounded-[40px] shadow-sm border border-slate-200 dark:border-slate-800 space-y-6 md:space-y-8 transition-colors">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
          <div className="space-y-1">
            <h3 className="text-xl font-black text-slate-800 dark:text-slate-100 uppercase tracking-tight">Análise Gerencial</h3>
            <p className="text-xs text-slate-400 dark:text-slate-500 font-bold">Monitoramento de Atribuições e Realizações</p>
          </div>
          <div className="flex p-1 bg-slate-100 dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 overflow-x-auto custom-scrollbar">
            {[
              { id: 'common', label: 'PROCESSOS / ATRIBUIÇÕES' },
              { id: 'special', label: 'LICITAÇÃO / DIÁRIA' }
            ].map(tab => (
              <button 
                key={tab.id}
                onClick={() => setActiveTab(tab.id as TabType)}
                className={`px-4 md:px-6 py-2 md:py-2.5 rounded-xl text-[9px] md:text-[10px] font-black tracking-widest transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm border border-slate-200 dark:border-slate-600' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600 dark:hover:text-slate-300'}`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        <div className="pt-6 md:pt-8 border-t border-slate-100 dark:border-slate-800 space-y-6">
           <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
              <div className="flex flex-wrap gap-2">
                {presets.map(p => (
                  <button key={p.id} onClick={() => setActivePreset(p.id)} className={`px-3 md:px-4 py-2 rounded-xl text-[9px] md:text-[10px] font-black border transition-all ${activePreset === p.id ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'bg-white dark:bg-slate-800 text-slate-400 dark:text-slate-500 border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700'}`}>
                    {p.label.toUpperCase()}
                  </button>
                ))}
              </div>

              <div className="flex flex-wrap items-center gap-4 bg-slate-50/50 dark:bg-slate-800/50 p-3 rounded-2xl border border-slate-100 dark:border-slate-800">
                <div className="flex flex-col">
                  <span className="text-[8px] font-black text-slate-400 dark:text-slate-500 uppercase ml-1 mb-1">Início</span>
                  <input type="date" value={startDate} onChange={(e) => { setStartDate(e.target.value); setActivePreset('custom'); }} className="bg-white dark:bg-slate-800 text-[11px] font-bold text-slate-700 dark:text-slate-200 outline-none border border-slate-200 dark:border-slate-700 rounded-lg px-2 py-1" />
                </div>
                <div className="flex flex-col">
                  <span className="text-[8px] font-black text-slate-400 dark:text-slate-500 uppercase ml-1 mb-1">Fim</span>
                  <input type="date" value={endDate} onChange={(e) => { setEndDate(e.target.value); setActivePreset('custom'); }} className="bg-white dark:bg-slate-800 text-[11px] font-bold text-slate-700 dark:text-slate-200 outline-none border border-slate-200 dark:border-slate-700 rounded-lg px-2 py-1" />
                </div>
                <button onClick={handleManualRefresh} disabled={isRefreshing} className="flex items-center gap-2 p-2 rounded-xl bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:text-blue-600 transition-all active:scale-95 disabled:opacity-50">
                  <div className={isRefreshing ? 'animate-spin-slow' : ''}><Icons.Refresh /></div>
                </button>
              </div>
            </div>

            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <Icons.People /> Filtrar por Colaborador
                </span>
                {selectedPeopleIds.length > 0 && <button onClick={clearPeopleFilter} className="text-[10px] font-black text-blue-600 dark:text-blue-400 hover:underline">LIMPAR FILTRO</button>}
              </div>
              <div className="flex flex-wrap gap-2">
                {state.people.map(person => {
                  const isSelected = selectedPeopleIds.includes(person.id);
                  return (
                    <button key={person.id} onClick={() => togglePerson(person.id)} className={`px-3 py-1.5 rounded-full text-[10px] font-bold transition-all border ${isSelected ? 'bg-blue-100 border-blue-200 text-blue-700 dark:bg-blue-900/40 dark:border-blue-800 dark:text-blue-300 ring-2 ring-blue-500/20' : 'bg-slate-50 border-slate-100 text-slate-500 dark:bg-slate-800/50 dark:border-slate-800 dark:text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'}`}>
                      {person.name}
                    </button>
                  );
                })}
              </div>
            </div>
        </div>
      </div>

      {/* CARDS */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 md:gap-6">
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-indigo-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Processos Atribuídos</p>
          <h4 className="text-3xl md:text-4xl font-black text-indigo-600 dark:text-indigo-400 mt-1 md:mt-2">
            {tasksForDetailedCharts.reduce((acc, t) => acc + (isSpecialCategory(t.serviceCategoryId) === (activeTab === 'special') ? (Number(t.assignedProcesses) || 0) : 0), 0)}
          </h4>
        </div>
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-blue-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Processos Realizados</p>
          <h4 className="text-3xl md:text-4xl font-black text-blue-600 dark:text-blue-500 mt-1 md:mt-2">
            {tasksForDetailedCharts.reduce((acc, t) => acc + (isSpecialCategory(t.serviceCategoryId) === (activeTab === 'special') ? (Number(t.processQuantity) || 0) : 0), 0)}
          </h4>
        </div>
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-emerald-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Notas Fiscais</p>
          <h4 className="text-3xl md:text-4xl font-black text-emerald-600 dark:text-emerald-400 mt-1 md:mt-2">
            {tasksForDetailedCharts.reduce((acc, t) => acc + (isSpecialCategory(t.serviceCategoryId) === (activeTab === 'special') ? (Number(t.invoiceQuantity) || 0) : 0), 0)}
          </h4>
        </div>
        <div className="bg-white dark:bg-slate-900 p-5 md:p-7 rounded-[24px] md:rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800 border-l-[6px] border-l-amber-500 transition-colors">
          <p className="text-[9px] md:text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Resumo {activeTab === 'common' ? 'Geral' : 'Especial'}</p>
          <h4 className="text-3xl md:text-4xl font-black text-amber-600 dark:text-amber-500 mt-1 md:mt-2">
            {currentPieData.length} <span className="text-xs uppercase opacity-40">Tipos</span>
          </h4>
        </div>
      </div>

      {/* GRAFICOS */}
      <div className="space-y-8">
        <div className="bg-white dark:bg-slate-900 p-6 md:p-10 rounded-[32px] md:rounded-[48px] shadow-sm border border-slate-200 dark:border-slate-800 transition-colors">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-xl md:text-2xl font-black text-slate-800 dark:text-slate-100 uppercase tracking-tight">Performance por Analista ({activeTab === 'common' ? 'Operacional' : 'Especial'})</h3>
            <span className="text-[9px] font-black text-slate-400 uppercase bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-full">Clique na barra para filtrar</span>
          </div>
          <div className="chart-container-lg">
            {currentBarData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={currentBarData} margin={{ top: 30, right: 10, left: -20, bottom: 20 }}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" className="dark:opacity-10" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={10} fontWeight={800} tick={{ fill: '#94a3b8' }} />
                  <YAxis axisLine={false} tickLine={false} fontSize={10} tick={{ fill: '#94a3b8' }} />
                  <Tooltip cursor={{fill: 'rgba(248, 250, 252, 0.05)'}} contentStyle={{ borderRadius: '12px', border: 'none', backgroundColor: '#1e293b', color: '#fff' }} />
                  <Legend verticalAlign="top" align="right" wrapperStyle={{ paddingBottom: '30px', fontSize: '10px' }} formatter={(value) => <span className="text-slate-500 dark:text-slate-400 font-bold uppercase">{value}</span>} />

                  <Bar dataKey="atribuidos" name="Atribuídos" fill="#6366f1" radius={[4, 4, 0, 0]} barSize={24} onClick={(data) => togglePerson(data.id)} style={{ cursor: 'pointer' }}>
                    <LabelList dataKey="atribuidos" position="top" style={{ fill: '#6366f1', fontSize: 10, fontWeight: 900 }} />
                    {currentBarData.map((entry, index) => <Cell key={`c0-${index}`} fillOpacity={entry.opacity} />)}
                  </Bar>
                  <Bar dataKey="realizados" name="Realizados" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={24} onClick={(data) => togglePerson(data.id)} style={{ cursor: 'pointer' }}>
                    <LabelList dataKey="realizados" position="top" style={{ fill: '#3b82f6', fontSize: 10, fontWeight: 900 }} />
                    {currentBarData.map((entry, index) => <Cell key={`c1-${index}`} fillOpacity={entry.opacity} />)}
                  </Bar>
                  <Bar dataKey="notas" name="Notas Fiscais" fill="#10b981" radius={[4, 4, 0, 0]} barSize={24} onClick={(data) => togglePerson(data.id)} style={{ cursor: 'pointer' }}>
                    <LabelList dataKey="notas" position="top" style={{ fill: '#10b981', fontSize: 10, fontWeight: 900 }} />
                    {currentBarData.map((entry, index) => <Cell key={`c2-${index}`} fillOpacity={entry.opacity} />)}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            ) : <EmptyNotice msg="Nenhum registro encontrado." />}
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Gráfico de Tendência */}
          <div className="bg-white dark:bg-slate-900 p-6 md:p-10 rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800">
            <h3 className="text-lg md:text-xl font-black text-slate-800 dark:text-slate-100 mb-6 uppercase tracking-tight">Tendência de Produção {selectedPeopleIds.length > 0 && <span className="text-blue-500 text-xs ml-2">(Filtrado)</span>}</h3>
            <div className="chart-container-md h-[300px]">
              {currentAreaData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={currentAreaData} margin={{ top: 20, right: 10, left: -20, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" className="dark:opacity-10" />
                    <XAxis dataKey="date" fontSize={9} stroke="#94a3b8" tickFormatter={(v) => v.split('-').slice(1).reverse().join('/')} />
                    <YAxis fontSize={9} stroke="#94a3b8" />
                    <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', backgroundColor: '#1e293b', color: '#fff' }} />
                    <Area type="monotone" dataKey="realizados" name="Realizados" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.1} strokeWidth={4}>
                       <LabelList dataKey="realizados" position="top" offset={10} style={{ fill: '#3b82f6', fontSize: 10, fontWeight: 900 }} />
                    </Area>
                  </AreaChart>
                </ResponsiveContainer>
              ) : <EmptyNotice msg="Sem histórico temporal para este filtro." />}
            </div>
          </div>

          {/* Gráfico de Pizza: Tipos de Serviços (Agora habilitado para ambas as abas) */}
          <div className="bg-white dark:bg-slate-900 p-6 md:p-10 rounded-[32px] shadow-sm border border-slate-200 dark:border-slate-800">
            <h3 className="text-lg md:text-xl font-black text-slate-800 dark:text-slate-100 mb-6 uppercase tracking-tight">Distribuição de Serviços {activeTab === 'special' ? 'Especiais' : 'Comuns'}</h3>
            <div className="chart-container-md h-[300px]">
              {currentPieData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={currentPieData}
                      cx="50%"
                      cy="50%"
                      labelLine={false}
                      outerRadius={100}
                      fill="#8884d8"
                      dataKey="value"
                      label={({ name, value }) => `${name}: ${value}`}
                    >
                      {currentPieData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={PRESET_COLORS[index % PRESET_COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', backgroundColor: '#1e293b', color: '#fff' }} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <EmptyNotice msg="Dados insuficientes para o gráfico." />}
            </div>
          </div>
        </div>

        {/* Diagnóstico IA */}
        <div className="bg-slate-900 dark:bg-slate-800 rounded-[32px] p-8 text-white relative overflow-hidden flex flex-col justify-center">
          <div className="absolute top-0 right-0 p-10 opacity-10"><Icons.Sparkles /></div>
          <h2 className="text-xl font-black uppercase tracking-widest mb-2">Diagnóstico IA</h2>
          <p className="text-slate-400 text-sm mb-6">Análise inteligente baseada no contexto de {activeTab === 'common' ? 'Processos' : 'Licitações'}.</p>
          {aiInsight ? (
            <div className="bg-white/5 p-5 rounded-2xl text-xs leading-relaxed max-h-[200px] overflow-y-auto custom-scrollbar">
              {aiInsight}
              <button onClick={() => setAiInsight(null)} className="block mt-4 text-[10px] font-black opacity-50 uppercase hover:opacity-100 transition-opacity">Limpar Análise</button>
            </div>
          ) : (
            <button onClick={handleGetInsights} disabled={loadingAi || tasksForDetailedCharts.length === 0} className="bg-blue-600 px-6 py-4 rounded-xl font-black text-xs uppercase hover:bg-blue-700 transition-all flex items-center justify-center gap-2 w-fit">
              {loadingAi ? <div className="animate-spin w-4 h-4 border-2 border-white/20 border-t-white rounded-full"></div> : <Icons.Sparkles />}
              Gerar Insights Estratégicos
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, AreaChart, Area, LabelList
} from 'recharts';
import { AppState, Task, ServiceCategory } from '../types';
import { Icons, PRESET_COLORS } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
  onRefresh?: () => Promise<void>;
}

type TabType = 'common' | 'special';
type PeriodPreset = 'hoje' | 'semanal' | 'quinzenal' | 'mensal' | 'trimestral' | 'anual' | 'custom';

const Dashboard: React.FC<DashboardProps> = ({ state, onRefresh }) => {
  const getLocalDateStr = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset();
    const localDate = new Date(d.getTime() - (offset * 60 * 1000));
    return localDate.toISOString().split('T')[0];
  };

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>(getLocalDateStr());
  const [activePreset, setActivePreset] = useState<PeriodPreset>('mensal');
  const [selectedPeopleIds, setSelectedPeopleIds] = useState<string[]>([]);
  const [activeTab, setActiveTab] = useState<TabType>('common');
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  useEffect(() => {
    const now = new Date();
    let start = new Date();

    switch (activePreset) {
      case 'hoje': break;
      case 'semanal': start.setDate(now.getDate() - 7); break;
      case 'quinzenal': start.setDate(now.getDate() - 15); break;
      case 'mensal': start.setDate(now.getDate() - 30); break;
      case 'trimestral': start.setDate(now.getDate() - 90); break;
      case 'anual': start.setDate(now.getDate() - 365); break;
      case 'custom': return;
    }

    setStartDate(getLocalDateStr(start));
    setEndDate(getLocalDateStr(now));
  }, [activePreset]);

  const isSpecialCategory = (categoryId: string) => {
    const cat = state.serviceCategories.find(c => c.id === categoryId);
    if (!cat) return false;
    const name = cat.name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    return name.includes('licitacao') || name.includes('diaria') || name.includes('contrato');
  };

  const togglePerson = (id: string) => {
    setSelectedPeopleIds(prev => 
      prev.includes(id) ? prev.filter(pId => pId !== id) : [...prev, id]
    );
  };

  const clearPeopleFilter = () => setSelectedPeopleIds([]);

  const handleManualRefresh = async () => {
    if (onRefresh) {
      setIsRefreshing(true);
      await onRefresh();
      setTimeout(() => setIsRefreshing(false), 600);
    }
  };

  const tasksByDate = useMemo(() => {
    return (state.tasks || []).filter(t => {
      return (!startDate || t.date >= startDate) && (!endDate || t.date <= endDate);
    });
  }, [state.tasks, startDate, endDate]);

  const tasksForDetailedCharts = useMemo(() => {
    return tasksByDate.filter(t => {
      return selectedPeopleIds.length === 0 || selectedPeopleIds.includes(t.personId);
    });
  }, [tasksByDate, selectedPeopleIds]);

  const processBarData = (tasks: Task[], onlySpecial: boolean) => {
    return (state.people || []).map(person => {
      const pTasks = tasks.filter(t => t.personId === person.id && isSpecialCategory(t.serviceCategoryId) === onlySpecial);
      const atribuidos = pTasks.reduce((acc, t) => acc + (Number(t.assignedProcesses) || 0), 0);
      const realizados = pTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0);
      const notas = pTasks.reduce((acc, t) => acc + (Number(t.invoiceQuantity) || 0), 0);
      const isSelected = selectedPeopleIds.length === 0 || selectedPeopleIds.includes(person.id);
      return { id: person.id, name: person.name, atribuidos, realizados, notas, opacity: isSelected ? 1 : 0.15 };
    }).filter(d => d.atribuidos > 0 || d.realizados > 0 || d.notas > 0).sort((a, b) => b.realizados - a.realizados);
  };

  const processAreaData = (tasks: Task[], onlySpecial: boolean) => {
    const map: Record<string, any> = {};
    tasks.filter(t => isSpecialCategory(t.serviceCategoryId) === onlySpecial).forEach(t => {
      if (!map[t.date]) map[t.date] = { date: t.date, realizados: 0 };
      map[t.date].realizados += (Number(t.processQuantity) || 0);
    });
    return Object.values(map).sort((a: any, b: any) => a.date.localeCompare(b.date));
  };

  const processPieData = (tasks: Task[], onlySpecial: boolean) => {
    const map: Record<string, number> = {};
    tasks.filter(t => isSpecialCategory(t.serviceCategoryId) === onlySpecial).forEach(t => {
      const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
      const name = cat?.name || 'Outros';
      map[name] = (map[name] || 0) + (Number(t.processQuantity) || 0);
    });
    return Object.entries(map).map(([name, value]) => ({ name, value }));
  };

  const commonBarData = useMemo(() => processBarData(tasksByDate, false), [state.people, tasksByDate, selectedPeopleIds]);
  const commonAreaData = useMemo(() => processAreaData(tasksForDetailedCharts, false), [tasksForDetailedCharts]);
  const commonPieData = useMemo(() => processPieData(tasksForDetailedCharts, false), [tasksForDetailedCharts, state.serviceCategories]);
  const specialPieData = useMemo(() => processPieData(tasksForDetailedCharts, true), [tasksForDetailedCharts, state.serviceCategories]);

  const handleGetInsights = async () => {
    if (tasksForDetailedCharts.length === 0) return;
    setLoadingAi(true);
    try {
      const insight = await getProductivityInsights(tasksForDetailedCharts, state.people, state.serviceCategories);
      setAiInsight(insight);
    } catch (e) {
      setAiInsight("Erro ao gerar análise inteligente.");
    } finally {
      setLoadingAi(false);
    }
  };

  const presets: { id: PeriodPreset, label: string }[] = [
    { id: 'hoje', label: 'Hoje' },
    { id: 'semanal', label: 'Semanal' },
    { id: 'quinzenal', label: 'Quinzenal' },
    { id: 'mensal', label: 'Mensal' },
    { id: 'anual', label: 'Anual' },
    { id: 'custom', label: 'Personalizado' }
  ];

  const EmptyNotice = ({ msg }: { msg: string }) => (
    <div className="flex flex-col items-center justify-center h-full p-10 bg-slate-50 dark:bg-slate-800/50 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-[32px] text-slate-300 dark:text-slate-600 transition-colors">
      <div className="opacity-20"><Icons.Calendar /></div>
      <p className="mt-4 font-black text-[10px] uppercase tracking-widest text-slate-400 dark:text-slate-500 text-center">{msg}</p>
    </div>
  );

  return (
    <div className="space-y-8 pb-20 fade-in">
      {/* FILTROS PRINCIPAIS */}
      <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[32px] md:rounded-[40px] shadow-sm border border-slate-200 dark:border-slate-800 space-y-6 md:space-y-8 transition-colors">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
          <div className="space-y-1">
            <h3 className="text-xl font-black text-slate-800 dark:text-slate-100 uppercase tracking-tight">Análise Gerencial</h3>
            <p className="text-xs text-slate-400 dark:text-slate-500 font-bold">Monitoramento de Atribuições e Realizações</p>
          </div>
          <div className="flex p-1 bg-slate-100 dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 overflow-x-auto custom-scrollbar">
            {[
              { id: 'common', label: 'PROCESSOS / ATRIBUIÇÕES' },
              { id: 'special', label: 'LICITAÇÃO / DIÁRIA' }
            ].map(tab => (
              <button 
                key={tab.id}
                onClick={() => setActiveTab(tab.id as TabType)}
                className={`px-4 md:px-6 py-2 md:py-2.5 rounded-xl text-[9px] md:text-[10px] font-black tracking-widest transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm border border-slate-200 dark:border-slate-600' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600 dark:hover:text-slate-300'}`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        <div className="pt-6 md:pt-8 border-t border-slate-100 dark:border-slate-800 space-y-6">
           <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
              <div className="flex flex-wrap gap-2">
                {presets.map(p => (
                  <button key={p.id} onClick={() => setActivePreset(p.id)} className={`px-3 md:px-4 py-2 rounded-xl text-[9px] md:text-[10px] font-black border transition-all ${activePreset === p.id ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'bg-white dark:bg-slate-800 text-slate-400 dark:text-slate-500 border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700'}`}>
                    {p.label.toUpperCase()}
                  </button>
                ))}
              </div>

              <div className="flex flex-wrap items-center gap-4 bg-slate-50/50 dark:bg-slate-800/50 p-3 rounded-2xl border border-slate-100 dark:border-slate-800">
                <div className="flex flex-col">
                  <span className="text-[8px] font-black text-slate-400 dark:text-slate-500 uppercase ml-1 mb-1">Início</span>
                  <input type="date" value={startDate} onChange={(e) => { setStartDate(e.target.value); setActivePreset('custom'); }} className="bg-white dark:bg-slate-800 text-[11px] font-bold text-slate-700 dark:text-slate-200 outline-none border border-slate-200 dark:border-slate-700 rounded-lg px-2 py-1" />
                </div>
                <div className="flex flex-col">
                  <span className="text-[8px] font-black text-slate-400 dark:text-slate-500 uppercase ml-1 mb-1">Fim</span>
                  <input type="date" value={endDate} onChange={(e) => { setEndDate(e.target.value); setActivePreset('custom'); }} className="bg-white dark:bg-slate-800 text-[11px] font-bold text-slate-700 dark:text-slate-200 outline-none border border-slate-200 dark:border-slate-700 rounded-lg px-2 py-1" />
                </div>
                <button onClick={handleManualRefresh} disabled={isRefreshing} className="flex items-center gap-2 p-2 rounded-xl bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:text-blue-600 transition-all active:scale-95 disabled:opacity-50">
                  <div className={isRefreshing ? 'animate-spin-slow' : ''}><Icons.Refresh /></div>
                </button>
              </div>
            </div>

            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center gap-2">
