import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { AppState } from '../types';

const supabaseUrl = process.env.SUPABASE_URL;
const supabaseAnonKey = process.env.SUPABASE_ANON_KEY;

export const supabase: SupabaseClient | null = (supabaseUrl && supabaseAnonKey) 
  ? createClient(supabaseUrl, supabaseAnonKey) 
  : null;

export const supabaseService = {
  async getState(): Promise<AppState | null> {
    if (!supabase) return null;
    try {
      const { data, error } = await supabase
        .from('app_data')
        .select('state')
        .eq('id', 'current_state')
        .maybeSingle();

      if (error) throw error;
      return data?.state as AppState || null;
    } catch (e) {
      console.error("Erro ao carregar do Supabase:", e);
      return null;
    }
  },

  async saveState(localState: AppState) {
    if (!supabase) return localState;

    try {
      // 1. Busca dados atuais da nuvem para merge
      const { data: remoteData } = await supabase
        .from('app_data')
        .select('state')
        .eq('id', 'current_state')
        .maybeSingle();

      const remoteState = remoteData?.state as AppState;

      let stateToSave = localState;

      if (remoteState) {
        // Função de merge para listas: Mantém itens novos de outros PCs e atualiza os existentes
        const mergeLists = <T extends { id: string }>(local: T[], remote: T[]): T[] => {
          const mergedMap = new Map<string, T>();
          // Adiciona remotos primeiro
          remote.forEach(item => mergedMap.set(item.id, item));
          // Sobrescreve com locais (o que você acabou de fazer tem prioridade)
          local.forEach(item => mergedMap.set(item.id, item));
          return Array.from(mergedMap.values());
        };

        stateToSave = {
          ...localState,
          people: mergeLists(localState.people || [], remoteState.people || []),
          tasks: mergeLists(localState.tasks || [], remoteState.tasks || []),
          particularities: mergeLists(localState.particularities || [], remoteState.particularities || []),
          serviceCategories: mergeLists(localState.serviceCategories || [], remoteState.serviceCategories || [])
        };
      }

      // 2. Salva o estado consolidado
      const { error } = await supabase
        .from('app_data')
        .upsert({ 
          id: 'current_state', 
          state: stateToSave,
          updated_at: new Date().toISOString()
        });

      if (error) throw error;
      return stateToSave;
    } catch (e) {
      console.error("Erro ao salvar no Supabase:", e);
      return localState;
    }
  }
};

import React, { useState, useEffect } from 'react';
import { Person, Task, AppState, ServiceCategory, UserRole, Particularity } from './types';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import PeopleManager from './components/PeopleManager';
import DailyLog from './components/DailyLog';
import ServiceManager from './components/ServiceManager';
import ParticularityManager from './components/ParticularityManager';
import Login from './components/Login';
import { DEFAULT_CATEGORIES, Icons } from './constants';
import { apiService } from './services/api';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'people' | 'logs' | 'services' | 'particularities'>('dashboard');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('app-theme');
    return (saved as 'light' | 'dark') || 'light';
  });

  const [state, setState] = useState<AppState>({ 
    people: [], 
    tasks: [], 
    particularities: [],
    serviceCategories: DEFAULT_CATEGORIES,
    userRole: 'master' 
  });

  const loadData = async () => {
    setIsSyncing(true);
    // IMPORTANTE: Preserva o role atual para não cair para 'basic' durante a sync
    const currentLocalRole = state.userRole;

    try {
      const savedState = await apiService.loadState();
      if (savedState) {
        setState({
          ...savedState,
          userRole: currentLocalRole, // Garante que MASTER continue MASTER
          particularities: savedState.particularities || [],
          tasks: savedState.tasks || [],
          people: savedState.people || [],
          serviceCategories: savedState.serviceCategories || DEFAULT_CATEGORIES
        });
      }
    } catch (error) {
      console.error("Erro no carregamento:", error);
    } finally {
      setTimeout(() => setIsSyncing(false), 600);
    }
  };

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('app-theme', theme);
  }, [theme]);

  useEffect(() => {
    async function init() {
      await loadData();
      setTimeout(() => setIsLoading(false), 800);
    }
    init();
  }, []);

  const persistState = async (newState: AppState) => {
    const currentLocalRole = state.userRole;
    // Atualiza a UI imediatamente mantendo o role
    const stateWithRole = { ...newState, userRole: currentLocalRole };
    setState(stateWithRole);

    try {
      const syncedState = await apiService.saveState(stateWithRole);
      if (syncedState) {
        setState({ ...syncedState, userRole: currentLocalRole });
      }
    } catch (e) {
      console.error("Falha na sincronização:", e);
    }
  };

  const handleLogin = (role: UserRole) => {
    setState(prev => ({ ...prev, userRole: role }));
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setActiveTab('dashboard');
  };

  const setUserRole = (role: UserRole) => {
    persistState({ ...state, userRole: role });
  };

  const toggleTheme = () => setTheme(prev => prev === 'light' ? 'dark' : 'light');

  const addPerson = (person: Person) => {
    if (state.userRole !== 'master') return;
    persistState({ ...state, people: [...(state.people || []), person] });
  };

  const removePerson = (id: string) => {
    if (state.userRole !== 'master') return;
    persistState({
      ...state,
      people: (state.people || []).filter(p => p.id !== id),
      tasks: (state.tasks || []).filter(t => t.personId !== id),
      particularities: (state.particularities || []).filter(p => p.personId !== id)
    });
  };

  const addTask = (task: Task) => {
    persistState({ ...state, tasks: [...(state.tasks || []), task] });
  };

  const editTask = (updatedTask: Task) => {
    persistState({
      ...state,
      tasks: (state.tasks || []).map(t => t.id === updatedTask.id ? updatedTask : t)
    });
  };

  const removeTask = (id: string) => {
    persistState({
      ...state,
      tasks: (state.tasks || []).filter(t => t.id !== id)
    });
  };

  const addParticularity = (p: Particularity) => {
    persistState({ 
      ...state, 
      particularities: [...(state.particularities || []), p] 
    });
  };

  const removeParticularity = (id: string) => {
    persistState({
      ...state,
      particularities: (state.particularities || []).filter(p => p.id !== id)
    });
  };

  const addServiceCategory = (cat: ServiceCategory) => {
    if (state.userRole !== 'master') return;
    persistState({ ...state, serviceCategories: [...(state.serviceCategories || []), cat] });
  };

  const removeServiceCategory = (id: string) => {
    if (state.userRole !== 'master') return;
    persistState({
      ...state,
      serviceCategories: (state.serviceCategories || []).filter(c => c.id !== id),
      tasks: (state.tasks || []).filter(t => t.serviceCategoryId !== id)
    });
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex flex-col items-center justify-center transition-colors">
        <div className="relative">
          <div className="w-20 h-20 border-4 border-blue-100 dark:border-slate-800 border-t-blue-600 rounded-full animate-spin"></div>
          <div className="absolute inset-0 flex items-center justify-center">
             <svg className="w-8 h-8 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
          </div>
        </div>
        <p className="mt-6 font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest text-xs animate-pulse">Iniciando Gerência Contábil...</p>
      </div>
    );
  }

  if (!isLoggedIn) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="flex min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 transition-colors">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        userRole={state.userRole}
        onRoleChange={setUserRole}
        onLogout={handleLogout}
        theme={theme}
        toggleTheme={toggleTheme}
      />

      <main className="flex-1 p-6 md:p-10 overflow-auto">
        <header className="mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h1 className="text-3xl font-bold text-slate-800 dark:text-slate-100 mb-1">
              {activeTab === 'dashboard' && 'Visão Geral'}
              {activeTab === 'people' && 'Gerenciar Equipe'}
              {activeTab === 'logs' && 'Registro Diário'}
              {activeTab === 'particularities' && 'Particularidades'}
              {activeTab === 'services' && 'Tipos de Serviço'}
            </h1>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={loadData}
              disabled={isSyncing}
              className={`flex items-center gap-2 px-4 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-sm transition-all active:scale-95 ${
                isSyncing ? 'bg-slate-200 dark:bg-slate-800 text-slate-400' : 'bg-white dark:bg-slate-800 text-blue-600 dark:text-blue-400 border border-blue-50 dark:border-slate-700 hover:bg-blue-50 dark:hover:bg-slate-700'
              }`}
            >
              <div className={isSyncing ? 'animate-spin' : ''}>
                <Icons.Refresh />
              </div>
              {isSyncing ? 'Sincronizando...' : 'Sincronizar Dados'}
            </button>
            <div className={`px-4 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-sm ${
              state.userRole === 'master' ? 'bg-indigo-600 text-white' : 'bg-emerald-600 text-white'
            }`}>
              {state.userRole === 'master' ? 'Acesso MASTER' : 'Acesso Básico'}
            </div>
          </div>
        </header>

        {activeTab === 'dashboard' && <Dashboard state={state} onRefresh={loadData} />}
        {activeTab === 'people' && state.userRole === 'master' && (
          <PeopleManager people={state.people} onAdd={addPerson} onRemove={removePerson} />
        )}
        {activeTab === 'logs' && (
          <DailyLog 
            tasks={state.tasks} 
            people={state.people} 
            categories={state.serviceCategories}
            onAddTask={addTask} 
            onEditTask={editTask}
            onRefresh={loadData}
            onRemoveTask={removeTask}
            userRole={state.userRole}
          />
        )}
        {activeTab === 'particularities' && (
          <ParticularityManager 
            particularities={state.particularities || []}
            people={state.people || []}
            onAdd={addParticularity}
            onRemove={removeParticularity}
          />
        )}
        {activeTab === 'services' && state.userRole === 'master' && (
          <ServiceManager 
            categories={state.serviceCategories} 
            onAdd={addServiceCategory} 
            onRemove={removeServiceCategory} 
            state={state}
            onImport={(imported) => persistState(imported)}
          />
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, AreaChart, Area, LabelList
} from 'recharts';
import { AppState, Task, ServiceCategory, Particularity } from '../types';
import { Icons, PRESET_COLORS } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
  onRefresh?: () => Promise<void>;
}

type PeriodPreset = 'hoje' | 'semanal' | 'quinzenal' | 'mensal' | 'trimestral' | 'anual' | 'custom';
type DashboardSubTab = 'geral' | 'licitacao-diaria';

const Dashboard: React.FC<DashboardProps> = ({ state, onRefresh }) => {
  const getLocalDateStr = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset();
    const localDate = new Date(d.getTime() - (offset * 60 * 1000));
    return localDate.toISOString().split('T')[0];
  };

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>(getLocalDateStr());
  const [activePreset, setActivePreset] = useState<PeriodPreset>('mensal');
  const [activeSubTab, setActiveSubTab] = useState<DashboardSubTab>('geral');
  const [selectedPeopleIds, setSelectedPeopleIds] = useState<string[]>([]);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  useEffect(() => {
    const now = new Date();
    let start = new Date();

    switch (activePreset) {
      case 'hoje': break;
      case 'semanal': start.setDate(now.getDate() - 7); break;
      case 'quinzenal': start.setDate(now.getDate() - 15); break;
      case 'mensal': start.setDate(now.getDate() - 30); break;
      case 'trimestral': start.setDate(now.getDate() - 90); break;
      case 'anual': start.setDate(now.getDate() - 365); break;
      case 'custom': return;
    }

    setStartDate(getLocalDateStr(start));
    setEndDate(getLocalDateStr(now));
  }, [activePreset]);

  const tasksByDate = useMemo(() => {
    return (state.tasks || []).filter(t => {
      return (!startDate || t.date >= startDate) && (!endDate || t.date <= endDate);
    });
  }, [state.tasks, startDate, endDate]);

