import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { AppState } from '../types';

const supabaseUrl = process.env.SUPABASE_URL;
const supabaseAnonKey = process.env.SUPABASE_ANON_KEY;

export const supabase: SupabaseClient | null = (supabaseUrl && supabaseAnonKey) 
  ? createClient(supabaseUrl, supabaseAnonKey) 
  : null;

export const supabaseService = {
  async getState(): Promise<AppState | null> {
    if (!supabase) return null;
    try {
      const { data, error } = await supabase
        .from('app_data')
        .select('state')
        .eq('id', 'current_state')
        .maybeSingle();

      if (error) throw error;
      return data?.state as AppState || null;
    } catch (e) {
      console.error("Erro ao carregar do Supabase:", e);
      return null;
    }
  },

  async saveState(localState: AppState) {
    if (!supabase) return localState;

    try {
      // 1. Busca dados atuais da nuvem para merge preventivo
      const { data: remoteData } = await supabase
        .from('app_data')
        .select('state')
        .eq('id', 'current_state')
        .maybeSingle();

      const remoteState = remoteData?.state as AppState;

      let stateToSave = localState;

      if (remoteState) {
        // Função de merge de segurança: 
        // Consolida o que está na nuvem com o que foi feito localmente sem apagar nada
        const mergeLists = <T extends { id: string }>(local: T[] = [], remote: T[] = []): T[] => {
          const mergedMap = new Map<string, T>();
          // Adiciona remotos primeiro (preserva o que já existe na nuvem)
          remote.forEach(item => mergedMap.set(item.id, item));
          // Sobrescreve/Adiciona locais (o que o usuário acabou de fazer)
          local.forEach(item => mergedMap.set(item.id, item));
          return Array.from(mergedMap.values());
        };

        stateToSave = {
          ...localState,
          people: mergeLists(localState.people, remoteState.people),
          tasks: mergeLists(localState.tasks, remoteState.tasks),
          particularities: mergeLists(localState.particularities, remoteState.particularities),
          serviceCategories: mergeLists(localState.serviceCategories, remoteState.serviceCategories)
        };
      }

      // Segurança Crítica: Não salva se as listas essenciais estiverem vazias e a remota tiver dados
      // Isso evita que um erro de carregamento local apague o banco de dados.
      if (remoteState && 
          localState.people.length === 0 && 
          remoteState.people.length > 0) {
          console.warn("⚠️ Sincronização bloqueada: Tentativa de apagar dados remotos com estado local vazio.");
          return remoteState;
      }

      // 2. Salva o estado consolidado
      const { error } = await supabase
        .from('app_data')
        .upsert({ 
          id: 'current_state', 
          state: stateToSave,
          updated_at: new Date().toISOString()
        });

      if (error) throw error;
      return stateToSave;
    } catch (e) {
      console.error("Erro ao salvar no Supabase:", e);
      return localState;
    }
  }
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, AreaChart, Area, LabelList
} from 'recharts';
import { AppState, Task, ServiceCategory, Particularity } from '../types';
import { Icons, PRESET_COLORS } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
  onRefresh?: () => Promise<void>;
}

type PeriodPreset = 'hoje' | 'semanal' | 'quinzenal' | 'mensal' | 'trimestral' | 'anual' | 'custom';
type DashboardSubTab = 'pagamento' | 'licitacao-diaria';

const Dashboard: React.FC<DashboardProps> = ({ state, onRefresh }) => {
  const getLocalDateStr = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset();
    const localDate = new Date(d.getTime() - (offset * 60 * 1000));
    return localDate.toISOString().split('T')[0];
  };

  // Inicia com "Hoje" por padrão
  const [activePreset, setActivePreset] = useState<PeriodPreset>('hoje');
  const [startDate, setStartDate] = useState<string>(getLocalDateStr());
  const [endDate, setEndDate] = useState<string>(getLocalDateStr());

  const [activeSubTab, setActiveSubTab] = useState<DashboardSubTab>('pagamento');
  const [selectedPeopleIds, setSelectedPeopleIds] = useState<string[]>([]);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  useEffect(() => {
    const now = new Date();
    let start = new Date();
    switch (activePreset) {
      case 'hoje': break;
      case 'semanal': start.setDate(now.getDate() - 7); break;
      case 'quinzenal': start.setDate(now.getDate() - 15); break;
      case 'mensal': start.setDate(now.getDate() - 30); break;
      case 'trimestral': start.setDate(now.getDate() - 90); break;
      case 'anual': start.setDate(now.getDate() - 365); break;
      case 'custom': return;
    }
    setStartDate(getLocalDateStr(start));
    setEndDate(getLocalDateStr(now));
  }, [activePreset]);

  // Filtros de Dados
  const tasksByDate = useMemo(() => {
    return (state.tasks || []).filter(t => (!startDate || t.date >= startDate) && (!endDate || t.date <= endDate));
  }, [state.tasks, startDate, endDate]);

  const tasksByAnalyst = useMemo(() => {
    return tasksByDate.filter(t => selectedPeopleIds.length === 0 || selectedPeopleIds.includes(t.personId));
  }, [tasksByDate, selectedPeopleIds]);

  const filteredTasks = useMemo(() => {
    return tasksByAnalyst.filter(t => {
      const isLicitacaoOuDiaria = t.serviceCategoryId === '3' || t.serviceCategoryId === '4';
      return activeSubTab === 'licitacao-diaria' ? isLicitacaoOuDiaria : !isLicitacaoOuDiaria;
    });
  }, [tasksByAnalyst, activeSubTab]);

  const currentParticularities = useMemo(() => {
    return (state.particularities || []).filter(p => 
      (!startDate || p.date >= startDate) && 
      (!endDate || p.date <= endDate) &&
      (selectedPeopleIds.length === 0 || selectedPeopleIds.includes(p.personId))
    ).sort((a, b) => b.date.localeCompare(a.date));
  }, [state.particularities, startDate, endDate, selectedPeopleIds]);

  const stats = useMemo(() => {
    return {
      atribuidos: filteredTasks.reduce((acc, t) => acc + (Number(t.assignedProcesses) || 0), 0),
      realizados: filteredTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0),
      notas: filteredTasks.reduce((acc, t) => acc + (Number(t.invoiceQuantity) || 0), 0)
    };
  }, [filteredTasks]);

  const barData = useMemo(() => {
    return (state.people || []).map(person => {
      const pTasks = filteredTasks.filter(t => t.personId === person.id);
      const atribuidos = pTasks.reduce((acc, t) => acc + (Number(t.assignedProcesses) || 0), 0);
      const realizados = pTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0);
      const isSelected = selectedPeopleIds.length === 0 || selectedPeopleIds.includes(person.id);
      return { name: person.name, atribuidos, realizados, opacity: isSelected ? 1 : 0.3 };
    }).filter(d => d.atribuidos > 0 || d.realizados > 0).sort((a, b) => b.realizados - a.realizados);
  }, [state.people, filteredTasks, selectedPeopleIds]);

  const areaData = useMemo(() => {
    const map: Record<string, any> = {};
    filteredTasks.forEach(t => {
      if (!map[t.date]) map[t.date] = { date: t.date, realizados: 0 };
      map[t.date].realizados += (Number(t.processQuantity) || 0);
    });
    return Object.values(map).sort((a: any, b: any) => a.date.localeCompare(b.date));
  }, [filteredTasks]);

  const pieData = useMemo(() => {
    const map: Record<string, number> = {};
    filteredTasks.forEach(t => {
      const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
      const name = cat?.name || 'Outros';
      map[name] = (map[name] || 0) + (Number(t.processQuantity) || 0);
    });
    return Object.entries(map).map(([name, value]) => ({ name, value }));
  }, [filteredTasks, state.serviceCategories]);

  const handleGetInsights = async () => {
    if (filteredTasks.length === 0) return;
    setLoadingAi(true);
    try {
      const insight = await getProductivityInsights(filteredTasks, state.people, state.serviceCategories, state.particularities);
      setAiInsight(insight);
    } catch (e) {
      setAiInsight("Erro ao gerar análise.");
    } finally {
      setLoadingAi(false);
    }
  };

  return (
    <div className="space-y-10 pb-20 fade-in">
      {/* Menu Superior e Filtros Estilizados */}
      <div className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl p-8 rounded-[40px] shadow-2xl shadow-slate-200/40 dark:shadow-none border border-slate-200/50 dark:border-slate-800 transition-all">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 mb-10">
          <div>
            <h3 className="text-3xl font-black text-slate-800 dark:text-slate-100 uppercase tracking-tighter">Cockpit Gerencial</h3>
            <div className="flex gap-3 mt-5">
               <button onClick={() => setActiveSubTab('pagamento')} className={`px-7 py-3 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all ${activeSubTab === 'pagamento' ? 'bg-blue-600 text-white shadow-xl shadow-blue-500/30' : 'bg-slate-100 dark:bg-slate-800 text-slate-400'}`}>Processos de Pagamento</button>
