import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { AppState } from '../types';

// Função para obter variáveis de ambiente de forma segura no navegador
const getSafeEnv = (key: string): string => {
  try {
    // Tenta acessar via process.env (injetado pelo Vite)
    return (typeof process !== 'undefined' && process.env && process.env[key]) || '';
  } catch (e) {
    return '';
  }
};

const supabaseUrl = getSafeEnv('SUPABASE_URL');
const supabaseAnonKey = getSafeEnv('SUPABASE_ANON_KEY');

// Diagnóstico silencioso
const isValidConfig = !!supabaseUrl && supabaseUrl.startsWith('http') && !!supabaseAnonKey && supabaseAnonKey.length > 10;

export const supabase: SupabaseClient | null = isValidConfig 
  ? createClient(supabaseUrl, supabaseAnonKey) 
  : null;

export const supabaseService = {
  isConfigured(): boolean {
    return !!supabase;
  },

  getConfigs() {
    return {
      hasUrl: !!supabaseUrl,
      hasKey: !!supabaseAnonKey,
      isValid: isValidConfig
    };
  },

  async getState(): Promise<AppState | null> {
    if (!supabase) return null;

    try {
      const { data, error } = await supabase
        .from('app_data')
        .select('state')
        .eq('id', 'current_state')
        .maybeSingle();

      if (error) {
        console.warn(`Supabase: ${error.message}`);
        return null;
      }

      return data?.state as AppState || null;
    } catch (e) {
      return null;
    }
  },

  async saveState(localState: AppState): Promise<AppState> {
    if (!supabase) return localState;

    try {
      const payload = { 
        id: 'current_state', 
        state: localState,
        updated_at: new Date().toISOString()
      };

      await supabase
        .from('app_data')
        .upsert(payload, { onConflict: 'id' });

      return localState;
    } catch (e) {
      return localState;
    }
  },

  subscribeToChanges(onUpdate: (newState: AppState) => void) {
    if (!supabase) return () => {};

    const channel = supabase
      .channel('public_app_data_sync')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'app_data', filter: 'id=eq.current_state' },
        (payload) => {
          if (payload.new && (payload.new as any).state) {
            onUpdate((payload.new as any).state as AppState);
          }
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }
};

import { GoogleGenAI } from "@google/genai";
import { Task, Person, ServiceCategory, Particularity } from "../types";

const getSafeApiKey = (): string => {
  try {
    return (typeof process !== 'undefined' && process.env && process.env.API_KEY) || '';
  } catch (e) {
    return '';
  }
};

const apiKey = getSafeApiKey();
const ai = apiKey ? new GoogleGenAI({ apiKey }) : null;

export async function getProductivityInsights(tasks: Task[], people: Person[], categories: ServiceCategory[], particularities: Particularity[] = []) {
  if (!ai) return "IA não configurada. Verifique a API_KEY.";
  if (tasks.length === 0) return "Ainda não há dados para análise no período selecionado.";

  const prompt = `
    Analise os dados de produtividade de uma equipe:
    Categorias: ${categories.map(c => c.name).join(', ')}
    Produção: ${tasks.length} registros.
    Particularidades: ${particularities.length} registros.
    Forneça uma análise executiva sobre vazão, gargalos e equilíbrio da equipe em Português do Brasil.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Erro IA:", error);
    return "Falha ao gerar insights da IA.";
  }
}

import React, { useState, useEffect } from 'react';
import { Person, Task, AppState, ServiceCategory, UserRole, Particularity } from './types';
import Sidebar from './components/Sidebar';
