import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { AppState } from '../types';

/**
 * Função ultra-segura para capturar variáveis de ambiente.
 * No Vite, process.env é substituído em tempo de build.
 */
const getSafeEnv = (key: string): string => {
  try {
    // @ts-ignore - Evita erros de tipo se process não estiver definido
    const envValue = typeof process !== 'undefined' && process.env ? process.env[key] : '';
    return envValue || '';
  } catch (e) {
    return '';
  }
};

const supabaseUrl = getSafeEnv('SUPABASE_URL');
const supabaseAnonKey = getSafeEnv('SUPABASE_ANON_KEY');

// Validação rigorosa das chaves antes de tentar criar o cliente
const isValidConfig = 
  typeof supabaseUrl === 'string' && 
  supabaseUrl.startsWith('http') && 
  typeof supabaseAnonKey === 'string' && 
  supabaseAnonKey.length > 20;

export const supabase: SupabaseClient | null = isValidConfig 
  ? createClient(supabaseUrl, supabaseAnonKey) 
  : null;

export const supabaseService = {
  isConfigured(): boolean {
    return !!supabase;
  },

  async getState(): Promise<AppState | null> {
    if (!supabase) return null;

    try {
      const { data, error } = await supabase
        .from('app_data')
        .select('state')
        .eq('id', 'current_state')
        .maybeSingle();

      if (error) {
        console.warn("Supabase (Informativo):", error.message);
        return null;
      }

      return data?.state as AppState || null;
    } catch (e) {
      return null;
    }
  },

  async saveState(localState: AppState): Promise<AppState> {
    if (!supabase) return localState;

    try {
      const payload = { 
        id: 'current_state', 
        state: localState,
        updated_at: new Date().toISOString()
      };

      await supabase
        .from('app_data')
        .upsert(payload, { onConflict: 'id' });

      return localState;
    } catch (e) {
      return localState;
    }
  },

  subscribeToChanges(onUpdate: (newState: AppState) => void) {
    if (!supabase) return () => {};

    try {
      const channel = supabase
        .channel('public_app_data_sync')
        .on(
          'postgres_changes',
          { event: '*', schema: 'public', table: 'app_data', filter: 'id=eq.current_state' },
          (payload) => {
            if (payload.new && (payload.new as any).state) {
              onUpdate((payload.new as any).state as AppState);
            }
          }
        )
        .subscribe();

      return () => {
        supabase.removeChannel(channel);
      };
    } catch (e) {
      return () => {};
    }
  }
};

import React, { useState, useEffect } from 'react';
import { Person, Task, AppState, ServiceCategory, UserRole, Particularity } from './types';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import PeopleManager from './components/PeopleManager';
