const supabaseUrl = process.env.SUPABASE_URL || '';
const supabaseAnonKey = process.env.SUPABASE_ANON_KEY || '';

const isValid = supabaseUrl.length > 10 && supabaseAnonKey.length > 10;

if (!isValid) {
  console.warn("⚠️ ATENÇÃO: Chaves do Supabase não detectadas! Verifique as Environment Variables no Render e faça um 'Clear Cache and Deploy'.");
}

export const supabase: SupabaseClient | null = isValid 
  ? createClient(supabaseUrl, supabaseAnonKey) 
  : null;

export const supabaseService = {
  isConfigured(): boolean {
    return !!supabase;
  },

  async getState(): Promise<AppState | null> {
    if (!supabase) return null;
    try {
      console.log("📡 Supabase: Buscando estado global...");
      const { data, error } = await supabase
        .from('app_data')
        .select('state')
        .eq('id', 'current_state')
        .maybeSingle();

      if (error) {
        console.error("❌ Erro Supabase (getState):", error.message);
        throw error;
      }

      if (data) console.log("✅ Supabase: Dados carregados com sucesso.");
      return data?.state as AppState || null;
    } catch (err) {
      console.error("❌ Erro crítico ao buscar dados na nuvem:", err);
      return null;
    }
  },

  async saveState(localState: AppState): Promise<AppState> {
    if (!supabase) return localState;
    try {
      console.log("📤 Supabase: Sincronizando alterações...");
      const { error } = await supabase.from('app_data').upsert({ 
        id: 'current_state', 
        state: localState,
        updated_at: new Date().toISOString()
      }, { onConflict: 'id' });

      if (error) {
        console.error("❌ Erro Supabase (saveState):", error.message);
        throw error;
      }

      console.log("✅ Supabase: Sincronização concluída.");
      return localState;
    } catch (err) {
      console.error("❌ Erro crítico ao salvar dados na nuvem:", err);
      return localState;
    }
  },

  subscribeToChanges(onUpdate: (newState: AppState) => void) {
    if (!supabase) {
      console.warn("⚠️ Realtime desativado: Cliente Supabase não inicializado.");
      return () => {};
    }

    console.log("🔔 Supabase: Escutando atualizações em tempo real...");
    const channel = supabase
      .channel('global_sync')
      .on(
        'postgres_changes', 
        { event: '*', schema: 'public', table: 'app_data', filter: 'id=eq.current_state' }, 
        (payload) => {
          console.log("🔄 Supabase: Nova atualização recebida de outro dispositivo!");
          if (payload.new && (payload.new as any).state) {
            onUpdate((payload.new as any).state as AppState);
          }
        }
      )
      .subscribe((status) => {
        console.log("📡 Status da conexão Realtime:", status);
      });

    return () => {
      console.log("🔕 Supabase: Parando escuta de atualizações.");
      supabase.removeChannel(channel);
    };
  }
};

