import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { AppState } from '../types';

// O Vite injeta essas variáveis através do vite.config.ts durante a build
const supabaseUrl = process.env.SUPABASE_URL || '';
const supabaseAnonKey = process.env.SUPABASE_ANON_KEY || '';

const isValid = supabaseUrl.length > 10 && supabaseAnonKey.length > 10;

if (!isValid) {
  console.error("%c🚨 ERRO: CONEXÃO SUPABASE FALHOU", "color: white; background: red; font-size: 16px; font-weight: bold; padding: 4px;");
  console.log("Verifique as Environment Variables no Render e use 'Clear Cache and Deploy'.");
}

export const supabase: SupabaseClient | null = isValid 
  ? createClient(supabaseUrl, supabaseAnonKey) 
  : null;

export const supabaseService = {
  isConfigured(): boolean {
    return !!supabase;
  },

  async getState(): Promise<AppState | null> {
    if (!supabase) return null;
    try {
      const { data, error } = await supabase
        .from('app_data')
        .select('state')
        .eq('id', 'current_state')
        .maybeSingle();

      if (error) {
        console.error("❌ Erro ao baixar dados:", error.message);
        return null;
      }

      return data?.state as AppState || null;
    } catch (err) {
      return null;
    }
  },

  async saveState(localState: AppState): Promise<void> {
    if (!supabase) return;
    try {
      const { error } = await supabase.from('app_data').upsert({ 
        id: 'current_state', 
        state: localState,
        updated_at: new Date().toISOString()
      }, { onConflict: 'id' });

      if (error) {
        console.error("❌ Falha na Sincronização:", error.message);
      } else {
        console.log("%c☁️ Enviado para Nuvem", "color: #10b981; font-weight: bold;");
      }
    } catch (err) {
      console.error("Erro crítico ao salvar:", err);
    }
  },

  subscribeToChanges(onUpdate: (newState: AppState) => void) {
    if (!supabase) return () => {};

    console.log("%c📡 Iniciando Escuta Real-time...", "color: #3b82f6; font-weight: bold;");

    const channel = supabase
      .channel('global_sync')
      .on(
        'postgres_changes', 
        { event: '*', schema: 'public', table: 'app_data', filter: 'id=eq.current_state' }, 
        (payload) => {
          console.log("%c🔄 DADOS REMOTOS RECEBIDOS", "color: white; background: #6366f1; font-weight: bold; padding: 2px 6px; border-radius: 4px;");
          if (payload.new && (payload.new as any).state) {
            onUpdate((payload.new as any).state as AppState);
          }
        }
      )
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          console.log("%c✅ CONECTADO AO SUPABASE REALTIME", "color: #10b981; font-weight: bold;");
        } else {
          console.log("📡 Status Realtime:", status);
        }
      });

    return () => {
      supabase.removeChannel(channel);
    };
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { Person, Task, AppState, ServiceCategory, UserRole, Particularity } from './types';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import PeopleManager from './components/PeopleManager';
import DailyLog from './components/DailyLog';
import ServiceManager from './components/ServiceManager';
import ParticularityManager from './components/ParticularityManager';
import Login from './components/Login';
import { DEFAULT_CATEGORIES, Icons } from './constants';
import { apiService } from './services/api';
import { supabaseService } from './services/supabase';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'people' | 'logs' | 'services' | 'particularities'>('dashboard');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSync, setLastSync] = useState<string | null>(null);
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    try {
      return (localStorage.getItem('app-theme') as 'light' | 'dark') || 'light';
    } catch { return 'light'; }
  });

  const [state, setState] = useState<AppState>({ 
    people: [], 
    tasks: [], 
    particularities: [],
    serviceCategories: DEFAULT_CATEGORIES,
    userRole: 'master' 
  });

  const loadData = useCallback(async () => {
    setIsSyncing(true);
    try {
      const data = await apiService.loadState();
      if (data) {
        setState(prev => ({ ...data, userRole: prev.userRole }));
        setLastSync(new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }));
      }
    } finally {
      setIsSyncing(false);
      setIsLoading(false);
    }
  }, []);

  // Efeito de Sincronização Automática entre PCs
  useEffect(() => {
    if (!isLoggedIn) return;

    // Conecta ao "rádio" do Supabase
    const unsubscribe = supabaseService.subscribeToChanges((newState) => {
      // Quando este PC "ouve" que outro PC salvou algo, ele atualiza o estado local
      setState(prev => ({ ...newState, userRole: prev.userRole }));
      setLastSync(new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
    });

    return () => unsubscribe();
  }, [isLoggedIn]);

  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
    localStorage.setItem('app-theme', theme);
  }, [theme]);

  useEffect(() => { 
    loadData(); 
  }, [loadData]);

  const persist = async (newState: AppState) => {
    // 1. Atualiza a interface IMEDIATAMENTE no computador atual
    setState(newState);
    // 2. Tenta salvar na nuvem (isso vai avisar todos os outros PCs via Realtime)
    await apiService.saveState(newState);
    setLastSync(new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
  };

  if (isLoading) return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex flex-col items-center justify-center">
      <div className="w-12 h-12 border-4 border-blue-600/20 border-t-blue-600 rounded-full animate-spin"></div>
      <p className="mt-4 text-[10px] font-black uppercase tracking-widest text-slate-400">Estabelecendo Conexão...</p>
    </div>
  );

  if (!isLoggedIn) return <Login onLogin={(role) => { setState(p => ({...p, userRole: role})); setIsLoggedIn(true); }} />;

  return (
    <div className="flex min-h-screen bg-slate-50 dark:bg-slate-950">
      <Sidebar 
        activeTab={activeTab} setActiveTab={setActiveTab} 
        userRole={state.userRole} onRoleChange={(role) => persist({...state, userRole: role})}
        onLogout={() => { setIsLoggedIn(false); setActiveTab('dashboard'); }}
        theme={theme} toggleTheme={() => setTheme(p => p === 'light' ? 'dark' : 'light')}
      />

      <main className="flex-1 p-6 md:p-10 overflow-auto">
        <header className="mb-10 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h1 className="text-3xl font-black text-slate-800 dark:text-slate-100 tracking-tighter uppercase">
              {activeTab === 'dashboard' && 'Dashboard'}
              {activeTab === 'people' && 'Equipe'}
              {activeTab === 'logs' && 'Registros'}
              {activeTab === 'particularities' && 'Ocorrências'}
              {activeTab === 'services' && 'Serviços'}
            </h1>
            <div className="flex items-center gap-2 mt-1">
               <div className={`w-1.5 h-1.5 rounded-full ${isSyncing ? 'bg-amber-500 animate-pulse' : 'bg-emerald-500'}`}></div>
               <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Sincronizado: {lastSync || '--:--'}</p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={loadData} disabled={isSyncing}
              className="flex items-center gap-2 px-6 py-3 bg-white dark:bg-slate-800 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-sm border border-slate-100 dark:border-slate-700 hover:bg-slate-50 transition-all active:scale-95 disabled:opacity-50"
            >
              <div className={isSyncing ? 'animate-spin' : ''}><Icons.Refresh /></div>
              {isSyncing ? 'Atualizando...' : 'Recarregar Tudo'}
            </button>
          </div>
        </header>

        <div className="min-h-0 min-w-0">
          {activeTab === 'dashboard' && <Dashboard state={state} onRefresh={loadData} />}
          {activeTab === 'people' && state.userRole === 'master' && (
            <PeopleManager people={state.people} onAdd={(p) => persist({...state, people: [...state.people, p]})} onRemove={(id) => persist({...state, people: state.people.filter(x => x.id !== id)})} />
          )}
          {activeTab === 'logs' && (
            <DailyLog 
              tasks={state.tasks} people={state.people} categories={state.serviceCategories}
              onAddTask={(t) => persist({...state, tasks: [...state.tasks, t]})} 
              onEditTask={(t) => persist({...state, tasks: state.tasks.map(x => x.id === t.id ? t : x)})}
              onRemoveTask={(id) => persist({...state, tasks: state.tasks.filter(x => x.id !== id)})}
              userRole={state.userRole} onRefresh={loadData}
            />
          )}
          {activeTab === 'particularities' && (
            <ParticularityManager 
              particularities={state.particularities} people={state.people}
              onAdd={(p) => persist({...state, particularities: [...state.particularities, p]})}
              onRemove={(id) => persist({...state, particularities: state.particularities.filter(x => x.id !== id)})}
            />
          )}
          {activeTab === 'services' && state.userRole === 'master' && (
            <ServiceManager 
              categories={state.serviceCategories} 
              onAdd={(c) => persist({...state, serviceCategories: [...state.serviceCategories, c]})} 
              onRemove={(id) => persist({...state, serviceCategories: state.serviceCategories.filter(x => x.id !== id)})} 
              state={state} onImport={(s) => persist(s)}
            />
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { ServiceCategory, AppState, Task } from '../types';
import { Icons, PRESET_COLORS } from '../constants';

interface ServiceManagerProps {
  categories: ServiceCategory[];
  onAdd: (category: ServiceCategory) => void;
  onRemove: (id: string) => void;
  state: AppState;
  onImport: (state: AppState) => void;
}

const ServiceManager: React.FC<ServiceManagerProps> = ({ categories, onAdd, onRemove, state, onImport }) => {
  const [name, setName] = useState('');
  const [selectedColor, setSelectedColor] = useState(PRESET_COLORS[0]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;

    onAdd({
      id: Math.random().toString(36).substr(2, 9),
      name: name.trim(),
      color: selectedColor
    });
    setName('');
  };

  const exportBackup = () => {
    const dataStr = JSON.stringify(state, null, 2);
    const dataUri = 'data:application/json;charset=utf-8,'+ encodeURIComponent(dataStr);

    const exportFileDefaultName = `prod360_backup_${new Date().toISOString().split('T')[0]}.json`;

    const linkElement = document.createElement('a');
    linkElement.setAttribute('href', dataUri);
    linkElement.setAttribute('download', exportFileDefaultName);
    linkElement.click();
  };

  const exportToExcel = () => {
    if (!state.tasks || state.tasks.length === 0) {
      alert("Não há lançamentos para exportar.");
      return;
    }

    // Cabeçalhos para o Excel
    const headers = ["Data", "Colaborador", "Servico", "Processos Atribuidos", "Qtd Realizada", "Notas Fiscais"];

    // Mapear os dados cruzando IDs com nomes reais
    const rows = state.tasks.map(task => {
      const person = state.people.find(p => p.id === task.personId)?.name || "Desconhecido";
      const category = state.serviceCategories.find(c => c.id === task.serviceCategoryId)?.name || "N/A";

      // Sanitizar campos para CSV (evitar quebra de linha ou aspas problemáticas)
      return [
        task.date,
        `"${person.replace(/"/g, '""')}"`,
        `"${category.replace(/"/g, '""')}"`,
        task.assignedProcesses || 0,
        task.processQuantity || 0,
        task.invoiceQuantity || 0
      ].join(";"); // Usar ponto e vírgula para compatibilidade com Excel PT-BR
    });

    // BOM (Byte Order Mark) para garantir que o Excel entenda como UTF-8
    const csvContent = "\uFEFF" + [headers.join(";"), ...rows].join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);

    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `relatorio_produtividade_total_${new Date().toISOString().split('T')[0]}.csv`);
    link.click();

    URL.revokeObjectURL(url);
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.people && json.tasks && json.serviceCategories) {
          if (confirm("Isso irá substituir todos os dados atuais. Deseja continuar?")) {
            onImport(json);
            alert("Dados importados com sucesso!");
          }
        } else {
          alert("Arquivo inválido. Certifique-se de que é um backup do Prod360.");
        }
      } catch (err) {
        alert("Erro ao processar o arquivo.");
      }
    };
    reader.readAsText(file);
    e.target.value = ''; // Reset input
  };

  return (
    <div className="space-y-8 pb-10">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="md:col-span-1 space-y-8">
          {/* Form Card */}
          <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-800 transition-colors">
            <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 mb-6">Novo Tipo de Serviço</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Nome do Serviço</label>
                <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="Ex: Consultoria Externa"
                  className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all placeholder:text-slate-300 dark:placeholder:text-slate-600"
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">Cor de Identificação</label>
                <div className="flex flex-wrap gap-2">
                  {PRESET_COLORS.map(color => (
                    <button
                      key={color}
                      type="button"
                      onClick={() => setSelectedColor(color)}
                      className={`w-8 h-8 rounded-full border-2 transition-all ${selectedColor === color ? 'border-slate-900 dark:border-white scale-110' : 'border-transparent'}`}
                      style={{ backgroundColor: color }}
                    />
                  ))}
                </div>
              </div>
              <button
                type="submit"
                className="w-full bg-slate-800 dark:bg-blue-600 text-white py-3 rounded-xl font-bold hover:bg-slate-900 dark:hover:bg-blue-700 transition-colors shadow-lg dark:shadow-none flex items-center justify-center gap-2"
              >
                <Icons.Plus />
                Salvar Serviço
              </button>
            </form>
          </div>

          {/* Database Card */}
          <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-800 transition-colors">
            <div className="flex items-center gap-3 mb-6">
              <div className="p-2 bg-slate-100 dark:bg-slate-800 rounded-lg text-slate-600 dark:text-slate-400">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 7v10c0 2.21 3.582 4 8 4s8-1.79 8-4V7M4 7c0 2.21 3.582 4 8 4s8-1.79 8-4M4 7c0-2.21 3.582-4 8-4s8 1.79 8 4m0 5c0 2.21-3.582 4-8 4s-8-1.79-8-4" /></svg>
              </div>
              <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100">Relatórios & Backup</h3>
            </div>
            <p className="text-xs text-slate-500 dark:text-slate-500 mb-6 font-medium leading-relaxed">
              Exportar todos os lançamentos históricos para Excel ou baixar um arquivo de backup do sistema.
            </p>
            <div className="space-y-3">
              <button
                onClick={exportToExcel}
                className="w-full flex items-center justify-center gap-2 py-3 px-4 bg-indigo-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200 dark:shadow-none active:scale-95"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                Exportar Lançamentos (Excel/CSV)
              </button>
              <div className="w-full h-px bg-slate-100 dark:bg-slate-800 my-2"></div>
              <button
                onClick={exportBackup}
                className="w-full flex items-center justify-center gap-2 py-3 px-4 bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-400 rounded-xl font-bold text-sm hover:bg-blue-100 dark:hover:bg-blue-900/40 transition-colors"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                Backup Completo (JSON)
              </button>
              <button
                onClick={handleImportClick}
                className="w-full flex items-center justify-center gap-2 py-3 px-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 rounded-xl font-bold text-sm hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                Restaurar Backup
              </button>
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                className="hidden" 
                accept=".json"
              />
            </div>
          </div>
        </div>

        <div className="md:col-span-2">
          <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-800 overflow-hidden transition-colors">
            <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center">
              <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100">Serviços Habilitados</h3>
              <span className="bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 px-3 py-1 rounded-full text-xs font-bold">
                {categories.length} Tipos
              </span>
            </div>

            <div className="divide-y divide-slate-100 dark:divide-slate-800">
              {categories.length === 0 ? (
                <div className="p-10 text-center text-slate-400 dark:text-slate-600">
                  <p>Nenhum tipo de serviço configurado.</p>
                </div>
              ) : (
                categories.map((cat) => (
                  <div key={cat.id} className="p-4 flex items-center justify-between hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                    <div className="flex items-center gap-4">
                      <div className="w-4 h-4 rounded-full shadow-sm" style={{ backgroundColor: cat.color }}></div>
                      <span className="font-semibold text-slate-800 dark:text-slate-200">{cat.name}</span>
                    </div>
                    <button
                      onClick={() => onRemove(cat.id)}
                      className="p-2 text-slate-400 dark:text-slate-500 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-all"
                      title="Excluir tipo de serviço"
                    >
                      <Icons.Trash />
                    </button>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ServiceManager;

import React, { useState, useMemo } from 'react';
import { Person, Particularity } from '../types';
import { Icons } from '../constants';

interface ParticularityManagerProps {
  particularities: Particularity[];
  people: Person[];
  onAdd: (p: Particularity) => void;
  onRemove: (id: string) => void;
}

const ParticularityManager: React.FC<ParticularityManagerProps> = ({ particularities, people, onAdd, onRemove }) => {
  const getLocalDateStr = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset();
    const localDate = new Date(d.getTime() - (offset * 60 * 1000));
    return localDate.toISOString().split('T')[0];
  };

  // State para o formulário
  const [selectedPerson, setSelectedPerson] = useState('');
  const [date, setDate] = useState(getLocalDateStr());
  const [type, setType] = useState<Particularity['type']>('Saúde');
  const [description, setDescription] = useState('');

  // State para os filtros
  const [filterStartDate, setFilterStartDate] = useState('');
  const [filterEndDate, setFilterEndDate] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPerson || !description.trim()) return;

    onAdd({
      id: Math.random().toString(36).substr(2, 9),
      personId: selectedPerson,
      date,
      type,
      description: description.trim()
    });

    setDescription('');
  };

  const filteredParticularities = useMemo(() => {
    let result = [...particularities];

    if (filterStartDate) {
      result = result.filter(p => p.date >= filterStartDate);
    }

    if (filterEndDate) {
      result = result.filter(p => p.date <= filterEndDate);
    }

    return result.sort((a, b) => b.date.localeCompare(a.date));
  }, [particularities, filterStartDate, filterEndDate]);

  const clearFilters = () => {
    setFilterStartDate('');
    setFilterEndDate('');
  };

  const getTypeStyle = (t: Particularity['type']) => {
    switch (t) {
      case 'Saúde': return 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400';
      case 'Treinamento': return 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400';
      case 'Administrativo': return 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400';
      default: return 'bg-slate-100 text-slate-700 dark:bg-slate-900/30 dark:text-slate-400';
    }
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-8 pb-10">
      <div className="md:col-span-1">
        <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-sm border border-slate-200 dark:border-slate-800 sticky top-6">
          <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 mb-6 flex items-center gap-2">
            <Icons.Note /> Registrar Ocorrência
          </h3>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-[10px] font-black uppercase text-slate-400 mb-1.5 tracking-wider">Colaborador</label>
              <select 
                value={selectedPerson} 
                onChange={(e) => setSelectedPerson(e.target.value)}
                className="w-full px-4 py-3 rounded-2xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white text-sm outline-none focus:ring-2 focus:ring-blue-500"
                required
              >
                <option value="">Selecione...</option>
                {people.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-[10px] font-black uppercase text-slate-400 mb-1.5 tracking-wider">Data</label>
              <input 
                type="date" 
                value={date} 
                onChange={(e) => setDate(e.target.value)}
                className="w-full px-4 py-3 rounded-2xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white text-sm outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
            <div>
              <label className="block text-[10px] font-black uppercase text-slate-400 mb-1.5 tracking-wider">Tipo</label>
              <div className="grid grid-cols-2 gap-2">
                {(['Saúde', 'Treinamento', 'Administrativo', 'Outros'] as const).map(t => (
                  <button
                    key={t}
                    type="button"
                    onClick={() => setType(t)}
                    className={`py-2 px-3 rounded-xl text-[10px] font-bold border transition-all ${type === t ? 'bg-blue-600 border-blue-600 text-white' : 'bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-700 text-slate-500'}`}
                  >
                    {t.toUpperCase()}
                  </button>
                ))}
              </div>
            </div>
            <div>
              <label className="block text-[10px] font-black uppercase text-slate-400 mb-1.5 tracking-wider">Descrição / Motivo</label>
              <textarea 
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                rows={3}
                placeholder="Ex: Consulta médica agendada para o período da manhã."
                className="w-full px-4 py-3 rounded-2xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white text-sm outline-none focus:ring-2 focus:ring-blue-500 resize-none"
                required
              />
            </div>
            <button
              type="submit"
              className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black text-[11px] uppercase tracking-widest hover:bg-blue-700 shadow-lg transition-all active:scale-95"
            >
              SALVAR REGISTRO
            </button>
          </form>
        </div>
      </div>

      <div className="md:col-span-2 space-y-4">
        {/* Filtros de Listagem */}
        <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-sm border border-slate-100 dark:border-slate-800 flex flex-wrap items-end gap-4">
          <div className="flex-1 min-w-[140px]">
             <label className="block text-[10px] font-black uppercase text-slate-400 mb-1.5 tracking-widest">Início do Período</label>
             <input 
               type="date" 
               value={filterStartDate} 
               onChange={(e) => setFilterStartDate(e.target.value)}
               className="w-full px-4 py-2.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-xs font-bold dark:text-white outline-none"
             />
          </div>
          <div className="flex-1 min-w-[140px]">
             <label className="block text-[10px] font-black uppercase text-slate-400 mb-1.5 tracking-widest">Fim do Período</label>
             <input 
               type="date" 
               value={filterEndDate} 
               onChange={(e) => setFilterEndDate(e.target.value)}
               className="w-full px-4 py-2.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-xs font-bold dark:text-white outline-none"
             />
          </div>
          <button 
            onClick={clearFilters}
            className="px-4 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest bg-slate-100 dark:bg-slate-800 text-slate-500 hover:bg-slate-200 transition-colors"
          >
            Limpar Filtros
          </button>
        </div>

        <div className="bg-white dark:bg-slate-900 rounded-3xl shadow-sm border border-slate-200 dark:border-slate-800 overflow-hidden">
          <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center">
            <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 tracking-tight">Histórico de Particularidades</h3>
            <span className="bg-slate-100 dark:bg-slate-800 text-slate-500 px-3 py-1 rounded-full text-[10px] font-black uppercase">
              {filteredParticularities.length} Registros
            </span>
          </div>

          <div className="divide-y divide-slate-100 dark:divide-slate-800">
            {filteredParticularities.length === 0 ? (
              <div className="p-16 text-center text-slate-400">
                <div className="bg-slate-50 dark:bg-slate-800 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                  <Icons.Note />
                </div>
                <p className="font-bold text-xs uppercase tracking-widest">Nenhuma particularidade encontrada para este período.</p>
              </div>
            ) : (
              filteredParticularities.map((p) => {
                const person = people.find(per => per.id === p.personId);
                return (
                  <div key={p.id} className="p-6 flex items-start justify-between hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors group">
                    <div className="flex gap-4">
                      <div className={`mt-1 w-10 h-10 rounded-xl flex items-center justify-center font-bold text-xs ${getTypeStyle(p.type)}`}>
                        {p.date.split('-').reverse().slice(0, 2).join('/')}
                      </div>
                      <div>
                        <div className="flex items-center gap-2 mb-1">
                          <p className="font-bold text-slate-800 dark:text-slate-100">{person?.name || '??'}</p>
                          <span className={`text-[9px] font-black px-2 py-0.5 rounded uppercase ${getTypeStyle(p.type)}`}>{p.type}</span>
                        </div>
                        <p className="text-sm text-slate-600 dark:text-slate-400 leading-relaxed">{p.description}</p>
                      </div>
                    </div>
                    <button
                      onClick={() => onRemove(p.id)}
                      className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-all opacity-0 group-hover:opacity-100"
                    >
                      <Icons.Trash />
                    </button>
                  </div>
                );
              })
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ParticularityManager;
